<template>
  <div ref="rootRef" class="v3d">
    <div ref="mountRef" class="v3d-canvas"></div>

    <!-- 加载遮罩 -->
    <div v-if="state.viewport.loading" class="v3d-cover">
      <div class="v3d-spin"></div>
      <p>正在加载模型…</p>
    </div>

    <!-- 错误提示 -->
    <div v-if="state.viewport.error" class="v3d-cover v3d-err">
      <p>{{ state.viewport.error }}</p>
    </div>

    <!-- 当前选中 -->
    <div v-if="selectedName" class="v3d-sel">
      <span class="v3d-sel-dot"></span>
      {{ selectedName }}
    </div>

    <!-- 底部状态 -->
    <div class="v3d-hud">
      <span class="v3d-hud-dot" :class="{ on: state.viewport.ready }"></span>
      <span>{{ state.viewport.ready ? '模型已就绪 · 单击部件聚焦 · 双击查看属性 · 拖拽旋转 / 滚轮缩放' : '加载中…' }}</span>
    </div>
  </div>
</template>

<script>
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue'
import * as THREE from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js'
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js'
import { editorState, selectItem, selectPart, clearSelection } from '../../lib/editorState'
import { SCALE } from '../../lib/catalog'
import { getCtx } from '../../lib/modelCtx'
import { getWallTexture, getFrostedTexture } from '../../lib/textures'

// 素材库 URL：两个模型共用同一份门窗素材（sucai.fbx），相对路径兼容子路径部署
const SUCAI_URL = 'Model/sucai.fbx'
const HL_COLOR = 0x2f6bff // 选中高亮蓝

/** 兜底视角预设（模型未加载时；加载后按包围盒动态计算） */
const VIEW_PRESETS = {
  front: { pos: [-3.6, 1.15, 0], target: [0, 0.58, 0] },   // 正视角 = X 负端墙（门面）
  left: { pos: [0, 1.15, -3.6], target: [0, 0.58, 0] },     // 左侧面 = Z 负端墙
  right: { pos: [0, 1.15, 3.6], target: [0, 0.58, 0] },     // 右侧面 = Z 正端墙
  top: { pos: [0, 4.6, 0.01], target: [0, 0, 0] }           // 俯视
}

/* ---------- 部件名 → 选中键 映射（从 catalog 派生，兼容编号部件；catalog 按当前模型传入） ---------- */
function buildKeyMap(cat) {
  const map = {}
  cat.sections.forEach((sec) => {
    if (sec.type === 'combo-list') {
      sec.items.forEach((it) => {
        it.parts.forEach((p) => {
          // partName = 子部件 mesh 名（组合体子部件可单独显隐）
          map[p.mesh] = { key: it.id, groupId: sec.id, groupName: sec.name, itemName: it.name, kind: 'combo', partName: p.mesh }
        })
      })
    } else {
      sec.groups.forEach((g) => {
        g.parts.forEach((p) => {
          map[p.mesh] = { key: p.id, groupId: sec.id, groupName: sec.name, itemName: p.name, kind: 'part', partName: p.mesh }
        })
      })
    }
  })
  return map
}

/** 由选中键找到 catalog 条目（组合体 → {section,item}；编号部件 → {section,item:group,part}） */
function findItem(key, cat) {
  for (const s of cat.sections) {
    if (s.type === 'combo-list') {
      const it = s.items.find((x) => x.id === key)
      if (it) return { section: s, item: it, kind: 'combo' }
    } else {
      for (const g of s.groups) {
        const p = g.parts.find((x) => x.id === key)
        if (p) return { section: s, item: g, part: p, kind: 'part' }
      }
    }
  }
  return null
}

export default {
  name: 'Viewer3D',
  setup() {
    const rootRef = ref(null)
    const mountRef = ref(null)
    const state = editorState

    /* ===== 当前模型上下文（切换模型时外层以 :key 重挂载本组件 → setup 重新执行） ===== */
    const ctx = getCtx()
    const catalog = ctx.catalog
    const MODEL_ORIG = ctx.MODEL_ORIG
    const MODEL_URL = ctx.url
    const features = ctx.meta.features || {}
    // 观察方向：front 方向可按模型配置（21 默认 X 负端墙；22 唯一真门 door1 亦在 X 负端墙，见 catalog meta.frontDir）
    const VIEW_DIRS = {
      front: Array.isArray(ctx.meta.frontDir) ? ctx.meta.frontDir.slice() : [-1, 0.3, 0],
      left: [0, 0.3, -1],
      right: [0, 0.3, 1],
      top: [0, 1, 0.0001]
    }
    const KEY_MAP = buildKeyMap(catalog)

    const autoRotate = ref(false)
    const showDims = ref(true) // 整体尺寸标注显示开关（顶栏控制；默认开启）

    // 尺寸标注：dimGroup = 3D 尺寸线；dimLabels = 屏幕标签 { el, pos(世界) }
    let dimGroup = null
    const dimLabels = []
    // 选中部件尺寸标注（跟随尺寸标注开关）
    let partDimGroup = null
    const partDimLabels = []

    const selectedName = computed(() => {
      const sel = editorState.selected
      if (!sel) return ''
      return sel.kind === 'combo' ? sel.item.name : (sel.part ? sel.part.name : '')
    })

    let renderer, scene, camera, controls, raycaster
    let hemiLight = null, keyLight = null, fillLight = null // 灯光引用（光照控制用）
    let root = null            // GLTF 场景根
    let gridHelper = null      // 地面网格
    let baseCenter = new THREE.Vector3() // GLB 原始中心（x/z，用于整体缩放后保持居中）
    const sizeGroups = {}      // 选中键 → 尺寸编辑专用 Group（首次编辑时 reparent）
    let meshes = [] // 全部 118 个 Mesh
    const assetLib = new Map() // 素材 id → { id, name, type, proto, size }（sucai.glb）
    const holders = {}         // 替换中的组合体：key → { group, assetId, sectionId }
    const assetMeshes = new Set() // 替换素材全部 mesh（持久记录，兼容开门时门扇挂到 pivot 的临时父子关系）
    const uploadCache = {}     // 上传纹理 id → THREE.Texture（'up-...'）
    let ro = null
    let animId = 0
    let flyAnim = 0
    let downPos = null
    let disposed = false
    // 门开合：门扇绕铰链轴旋转（door1 铰链在 z 负端 / door2 在 z 正端）
    let doorAnim = 0
    // 室内相机约束：门打开且相机处于内腔时，每帧把相机钳制在室内边界内
    let roomBox = null     // 内腔包围盒（世界坐标，开门时由墙体/屋顶实测推导）
    let flyRunning = false // 相机飞行动画进行中（此时不做室内钳制，避免与动画冲突）
    let wasInsideRoom = false // 上一帧相机是否处于内腔（用于进出时恢复/收紧 OrbitControls 参数）
    // 屋顶「俯视室内」模式：打开屋顶（隐藏）后相机自动飞到正上方俯视室内并限制在室内范围
    let roofOverlook = false // 俯视室内模式激活中
    let roofLookCenter = null // 俯视中心（内腔中心，米）

    /* ===== 初始化场景 ===== */
    function initScene() {
      const el = mountRef.value
      renderer = new THREE.WebGLRenderer({ antialias: true })
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
      renderer.setSize(el.clientWidth || 0.5, el.clientHeight || 0.5)
      renderer.domElement.style.display = 'block'
      // ACES 电影级色调映射：压缩高光，避免环境贴图+灯光叠加导致曝光过度（旧版同配置）
      renderer.toneMapping = THREE.ACESFilmicToneMapping
      renderer.toneMappingExposure = 1.0
      el.appendChild(renderer.domElement)

      scene = new THREE.Scene()
      scene.background = new THREE.Color(0xe9f0f8)

      // 环境贴图（RoomEnvironment）：为 MeshStandard/Physical 材质提供全局环境光，避免背光面全黑
      const pmrem = new THREE.PMREMGenerator(renderer)
      scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture

      camera = new THREE.PerspectiveCamera(40, 1, 0.05, 300)
      // 默认视角 = X 负端墙（门面）正视角
      camera.position.set(...VIEW_PRESETS.front.pos)

      controls = new OrbitControls(camera, renderer.domElement)
      controls.target.set(...VIEW_PRESETS.front.target)
      controls.enableDamping = true
      controls.dampingFactor = 0.08
      controls.minDistance = 0.5
      controls.maxDistance = 20

      // 灯光（环境贴图 + 半球 + 主光 + 补光）
      hemiLight = new THREE.HemisphereLight(0xffffff, 0x93a5bd, editorState.lighting.hemi)
      scene.add(hemiLight)
      keyLight = new THREE.DirectionalLight(0xffffff, editorState.lighting.key)
      keyLight.position.set(editorState.lighting.dirX, editorState.lighting.dirY, editorState.lighting.dirZ)
      scene.add(keyLight)
      fillLight = new THREE.DirectionalLight(0xbcd0f0, editorState.lighting.fill)
      fillLight.position.set(-5, 3, -6)
      scene.add(fillLight)

      // 地面网格辅助
      gridHelper = new THREE.GridHelper(6, 6, 0xb9c9dc, 0xd9e4f0)
      gridHelper.position.y = -0.005
      gridHelper.visible = editorState.display.grid
      scene.add(gridHelper)

      raycaster = new THREE.Raycaster()

      // 尺寸标注组（挂 root 下跟随模型缩放；模型加载后再 add 并构建标注）
      dimGroup = new THREE.Group()
      dimGroup.visible = false
      partDimGroup = new THREE.Group()
      partDimGroup.visible = false

      // 点击拾取（区分拖拽）
      renderer.domElement.addEventListener('pointerdown', onPointerDown)
      renderer.domElement.addEventListener('pointerup', onPointerUp)
      renderer.domElement.addEventListener('pointermove', onPointerMove)
      renderer.domElement.addEventListener('pointercancel', onPointerCancel)

      ro = new ResizeObserver(resize)
      ro.observe(rootRef.value)

      animate()
    }

    /* ===== 加载模型 ===== */
    // 主体簇：取景 / 居中 / 整体尺寸标注都只统计"主体部件"（模型 22 旧版导出曾含数公里外的
    // 游离大板/玻璃，2026-09-03 重导出后已全部归位；该逻辑保留作为防呆兜底——离群件照常显示但不拉爆取景）
    const CLUSTER_FAR = 12 // 米：部件中心离主体中位中心任一轴超过该距离即视为离群件
    let clusterMeshSet = null // 主体部件集合（加载时按几何中心距离判定一次）

    function refreshCluster() {
      clusterMeshSet = null
      if (!root || !meshes.length) return null
      root.updateMatrixWorld(true)
      const arr = meshes
        .map((o) => {
          const b = new THREE.Box3().setFromObject(o)
          if (b.isEmpty()) return null
          return { o, c: b.getCenter(new THREE.Vector3()) }
        })
        .filter(Boolean)
      if (!arr.length) return null
      const med = (k) => {
        const s = arr.map((x) => x.c.getComponent(k)).sort((a, b) => a - b)
        return s[Math.floor(s.length / 2)]
      }
      const cx = med(0), cy = med(1), cz = med(2)
      clusterMeshSet = new Set(
        arr
          .filter((x) =>
            Math.abs(x.c.x - cx) <= CLUSTER_FAR &&
            Math.abs(x.c.y - cy) <= CLUSTER_FAR &&
            Math.abs(x.c.z - cz) <= CLUSTER_FAR
          )
          .map((x) => x.o)
      )
      return clusterBoxNow()
    }
    function clusterBoxNow() {
      const box = new THREE.Box3()
      if (!clusterMeshSet || !clusterMeshSet.size) return box
      clusterMeshSet.forEach((o) => box.expandByObject(o))
      return box
    }

    /** 按分类 meta.relocate 平移"导出时被甩远的离群件"到目标位置（原始单位 → 场景米）。
     *  模型 22 旧版曾用此机制回填 Mesh190/194（门侧固定玻璃）；2026-09-03 重导出已归位，
     *  分类文件不再含 relocate，此函数空转保留备用。只平移整体姿态，不改旋转/缩放。 */
    function applyStrayRelocation() {
      const list = (ctx.meta && ctx.meta.relocate) || []
      if (!list.length || !root) return
      root.updateMatrixWorld(true)
      list.forEach((item) => {
        const o = meshes.find((m) => m.name === item.mesh || m.userData.partName === item.mesh)
        if (!o) return
        const b = new THREE.Box3().setFromObject(o)
        if (b.isEmpty()) return
        const c = b.getCenter(new THREE.Vector3())
        const target = new THREE.Vector3(item.center[0] * SCALE, item.center[1] * SCALE, item.center[2] * SCALE)
        o.position.add(target.sub(c))
      })
    }

    function loadModel() {
      state.viewport.loading = true
      state.viewport.error = ''
      new GLTFLoader().load(
        MODEL_URL,
        (gltf) => {
          root = gltf.scene
          root.scale.setScalar(SCALE)
          scene.add(root)

          // 收集全部 Mesh 并挂分组信息
          root.traverse((o) => {
            if (!o.isMesh) return
            // 多 primitive（多材质）节点：GLTFLoader 生成 Group(节点名，如 Mesh117)
            // + 子 Mesh(命名 mesh_索引)；子 mesh 名不在 KEY_MAP，需向上找命名父级
            let info = KEY_MAP[o.name]
            if (!info) {
              let p = o.parent
              while (p && !info) {
                info = KEY_MAP[p.name]
                p = p.parent
              }
            }
            o.userData.key = info ? info.key : ''
            o.userData.groupId = info ? info.groupId : ''
            o.userData.groupName = info ? info.groupName : ''
            o.userData.partName = info ? (info.partName || info.itemName || o.name) : o.name
            // 材质实例化，保证高亮互不影响
            if (Array.isArray(o.material)) {
              o.material = o.material.map((m) => m.clone())
            } else if (o.material) {
              o.material = o.material.clone()
            }
            // 记录原始贴图（墙体贴图恢复用）
            const mats = Array.isArray(o.material) ? o.material : [o.material]
            o.userData.origMaps = mats.map((m) => (m.map ? m.map : null))
            meshes.push(o)
          })

          // 离群件回填（meta.relocate，若有）
          applyStrayRelocation()

          // 主体簇判定 + 整体居中（x/z），底部贴地（y 不动）
          root.updateMatrixWorld(true)
          const c = (refreshCluster() || new THREE.Box3().setFromObject(root)).getCenter(new THREE.Vector3())
          baseCenter.set(c.x / SCALE, 0, c.z / SCALE) // GLB 原始中心（x/z）
          root.position.x -= c.x
          root.position.z -= c.z
          refreshCluster() // 居中后重算一次主体簇盒（坐标已平移）

          // 回填各选中键的实际尺寸（米）
          backfillSizes()

          // 初始化玻璃质感（默认 65% 透明 + 磨砂）
          applyGlassStyle('all')
          // 回填门窗组合体玻璃信息（UI 显示/隐藏独立玻璃设置项）
          refreshAllGlassInfo()

          // 尺寸标注组挂 root（跟随模型缩放），并构建整体尺寸标注
          if (dimGroup) {
            root.add(dimGroup)
            root.add(partDimGroup)
            rebuildDims()
          }

          state.viewport.loading = false
          state.viewport.ready = true

          // 若已从部件库选中，联动高亮
          if (editorState.selected) syncHighlight(editorState.selected)
          resize()
          // 初始机位按当前视口自适应取景（手机竖屏必须拉远，否则整箱撑出画面）
          {
            const v0 = presetView('front')
            camera.position.copy(v0.pos)
            controls.target.copy(v0.target)
            controls.update()
          }
        },
        undefined,
        (err) => {
          state.viewport.loading = false
          state.viewport.error = '模型加载失败：' + (err && err.message ? err.message : String(err))
        }
      )
    }

    /* ===== 门窗素材库（sucai.fbx：door1/door2 + window1/window2 四组原型） ===== */
    function loadAssets() {
      new FBXLoader().load(
        SUCAI_URL,
        (scene) => {
          try {
            buildAssetLibrary(scene)
          } catch (err) {
            console.warn('素材库解析失败，门窗替换不可用', err)
          }
        },
        undefined,
        () => console.warn('sucai.fbx 加载失败，门窗替换不可用')
      )
    }

    /** 素材主体包围盒：排除透明玻璃层（大平面会撑偏整体 box 中心，导致窗框/门板不居中） */
    function mainBoxOf(obj) {
      const box = new THREE.Box3()
      let count = 0
      obj.traverse((o) => {
        if (!o.isMesh) return
        const mat = Array.isArray(o.material) ? o.material[0] : o.material
        if (/glass/i.test(o.name || '') || (mat && mat.name && /glass/i.test(mat.name))) return
        box.expandByObject(o)
        count++
      })
      return count ? box : new THREE.Box3().setFromObject(obj)
    }

    function buildAssetLibrary(gltfScene) {
      // 新 sucai.glb（13.5MB / 16 顶层节点）：平铺命名 <原型>_<角色>
      //   door1_frame / door1_left_door_leaf / door1_right_door_leaf / door1_*_handle（门：框+左右门扇+把手）
      //   window1_frame / window1_glass / window1_lock；window2_frame / window2_glass / window2_Hardware
      // 按"原型名"（去掉末尾 _角色）分组重建素材；轴向：厚度 X、宽度 Z、高度 Y、正面朝 +X
      // 注意：GLB 里 door1_frame 节点名实际是 "_door1_frame"（带下划线前缀），需容忍
      const re = /^_?(door|window)(\d+)_(.+)$/
      gltfScene.updateMatrixWorld(true)
      const buckets = new Map()
      gltfScene.children.forEach((node) => {
        // 注意：GLB 节点名可能带下划线前缀（如 "_door1_frame"），先 trim 再匹配
        const raw = node.name || ''
        const m = re.exec(raw.trim())
        if (!m) return
        const protoName = m[1] + m[2] // door1 / door2 / window1 / window2
        if (!buckets.has(protoName)) buckets.set(protoName, { type: m[1], nodes: [] })
        buckets.get(protoName).nodes.push(node)
      })
    /**
     * 素材材质归一化：FBXLoader 导出的是 MeshPhongMaterial（Blender PBR 无直接对应，导出成 Phong
     * 近似；且 EmissiveColor=白(1,1,1) 让材质自发光"灰白"，是素材看起来发灰的元凶之一）。
     * 统一转为 MeshStandardMaterial（与主模型同一 PBR 光照体系）：
     *  - 【颜色修正】Blender 导出的 FBX DiffuseColor 存的是线性物理值（如 0.0392 = 深灰 #383838
     *    的 linear），FBXLoader 又按 sRGB 转换了一次（convertSRGBToLinear(0.0392)≈0.00304）导致
     *    颜色被压暗 ~13 倍 → 近黑。这里 convertLinearToSRGB() 还原回 FBX 原始线性值，恢复设计色
     *  - emissive 清黑（防白自发光"灰白"观感）
     *  - metalness=0 / roughness≈0.55 与主模型一致
     */
    function normalizeAssetMaterial(mat) {
      if (!mat) return mat
      if (mat.type === 'MeshStandardMaterial' || mat.type === 'MeshPhysicalMaterial') return mat
      const isGlass = /glass/i.test(mat.name || '')
      const col = (mat.color || new THREE.Color(0xffffff)).clone()
      // 还原 FBXLoader 的二次 sRGB→linear 转换（FBX DiffuseColor 本身已是 linear 值）
      col.convertLinearToSRGB()
      const std = new THREE.MeshStandardMaterial({
        name: mat.name,
        color: col,
        map: mat.map || null,
        transparent: mat.transparent,
        opacity: mat.opacity,
        depthWrite: mat.depthWrite,
        side: mat.side,
        metalness: 0,
        roughness: isGlass ? 0.1 : 0.55,
        emissive: new THREE.Color(0x000000)
      })
      if (std.userData === undefined) std.userData = {}
      return std
    }

    buckets.forEach((info, protoName) => {
        // 整组克隆 → 姿态归一化：把素材自带旋转/缩放（FBX Lcl Rotation/Scaling，Blender 导出
        // 时会写入 -90°X 轴转换 + 对象自身绕竖轴旋转）bake 进几何顶点，平移保留（节点间相对位置）。
        // 归一化后素材为标准轴向（厚 X / 宽 Z / 高 Y / 正面 +X），
        // 消除自带旋转对 buildAssetReplacement 轴向假设与开门铰链基准的干扰。
        const proto = new THREE.Group()
        info.nodes.forEach((n) => {
          const c = n.clone(true)
          c.traverse((o) => {
            if (!o.isMesh) return
            const geo = o.geometry.clone()
            const m = new THREE.Matrix4().makeRotationFromQuaternion(o.quaternion)
            m.scale(o.scale) // R·S：先缩放后旋转
            geo.applyMatrix4(m)
            o.geometry = geo
            o.quaternion.identity()
            o.scale.set(1, 1, 1)
            // 材质归一化：Phong → Standard（见 normalizeAssetMaterial 注释）
            if (Array.isArray(o.material)) o.material = o.material.map((mm) => normalizeAssetMaterial(mm))
            else o.material = normalizeAssetMaterial(o.material)
          })
          proto.add(c)
        })
        proto.updateMatrixWorld(true)
        // 【轴向归一化】确保素材标准轴向 厚 X / 宽 Z / 高 Y（buildAssetReplacement 依赖此映射）。
        // 不同素材导出轴向可能不同：旧 sucai 厚X/宽Z；sucai2 为 宽X/高Y/厚Z（最薄轴 Z）。
        // 最薄轴为 Z 时，几何绕 Y 旋转 -90°：原厚 Z → X、原宽 X → Z（高 Y 不变）。
        let s0 = mainBoxOf(proto).getSize(new THREE.Vector3())
        if (s0.z <= s0.x && s0.z <= s0.y) {
          const rotY = new THREE.Matrix4().makeRotationY(-Math.PI / 2)
          proto.traverse((o) => { if (o.isMesh) o.geometry.applyMatrix4(rotY) })
          proto.updateMatrixWorld(true)
        }
        const b = mainBoxOf(proto)
        if (b.isEmpty()) return
        const c = b.getCenter(new THREE.Vector3())
        const size = b.getSize(new THREE.Vector3())
        // 记录每个子节点相对原型的偏移，整体平移使中心归零
        proto.position.sub(c)
        proto.updateMatrixWorld(true)
        assetLib.set(protoName, {
          id: protoName,
          name: (info.type === 'door' ? '门 ' : '窗 ') + protoName.replace(/\D/g, '').padStart(2, '0'),
          type: info.type,
          proto,
          size,
          // 归一化后素材轴向：厚 X / 宽 Z / 高 Y（替换时按此映射缩放）
          thickness: size.x, width: size.z, height: size.y
        })
      })
      editorState.assets.list = Array.from(assetLib.values()).map((a) => ({ id: a.id, name: a.name, type: a.type }))
      editorState.assets.loaded = assetLib.size > 0
    }

    /**
     * 用素材克隆适配开口：宽高拉伸贴合、厚度贴开口法向、正面朝外。
     * 新 sucai.glb 素材轴向：厚度沿 X、宽度沿 Z、高度沿 Y、正面（门扇/把手侧）朝 +X。
     */
    function buildAssetReplacement(asset, box) {
      const size = box.getSize(new THREE.Vector3())
      const center = box.getCenter(new THREE.Vector3())
      // 开口法向 = 包围盒最薄轴
      const dims = [['x', size.x], ['y', size.y], ['z', size.z]].sort((a, b) => a[1] - b[1])
      const nAxis = dims[0][0]
      const g = asset.proto.clone(true) // 深克隆：避免污染素材原型
      // 法向对齐：素材厚度原沿 X（正面朝 +X）
      //   - 开口法向 X：不旋转；若在 X 负端墙（center.x<0）需翻 180° 让正面朝外（-X）
      //   - 开口法向 Z：绕 Y 转 90°（+X→-Z / -X→+Z），按端墙正负取对应方向
      if (nAxis === 'z') g.rotation.y = center.z > 0 ? -Math.PI / 2 : Math.PI / 2
      else if (nAxis === 'x' && center.x < 0) g.rotation.y = Math.PI
      // 目标尺寸：宽度取开口面内另一轴，高度取 Y，厚度取开口法向厚度
      let targetW
      if (nAxis === 'x') targetW = size.z
      else if (nAxis === 'z') targetW = size.x
      else targetW = Math.max(size.x, size.z) // 天窗退化处理
      const targetH = size.y
      const targetT = Math.max(size[nAxis], 0.02) // 厚度贴开口法向原值，避免素材凸出墙面
      // 缩放：素材 厚 X / 宽 Z / 高 Y → 在 g 的局部轴向上乘算（Three 先 scale 后 rotate，故按未旋转前轴向对应）
      const kx = Math.max(targetT, 0.01) / Math.max(asset.size.x, 0.01)
      const ky = Math.max(targetH, 0.05) / Math.max(asset.size.y, 0.01)
      const kz = Math.max(targetW, 0.05) / Math.max(asset.size.z, 0.01)
      g.scale.set(g.scale.x * kx, g.scale.y * ky, g.scale.z * kz)
      g.traverse((o) => {
        if (o.isMesh) { o.castShadow = true; o.receiveShadow = true }
      })
      g.position.copy(center)
      // 精确对齐：用「主体（非玻璃层）」包围盒中心与开口中心重合，避免透明玻璃层撑偏窗框位置
      g.updateMatrixWorld(true)
      const gb = mainBoxOf(g)
      const gc = gb.getCenter(new THREE.Vector3())
      g.position.add(center.clone().sub(gc))
      return g
    }

    /* ===== 替换素材后：组合体实际子部件清单（右侧「包含子部件」联动） ===== */
    /**
     * 由素材 mesh 自身/祖先节点名推导子部件标识（role-side）与中文名。
     * FBX 子 mesh 常挂在角色节点（如 door1_left_leaf）下，mesh 自身名可能是 Cube/Plane，
     * 因此向上拼祖先名再识别；材质名为 glass 的直接归为玻璃层。
     */
    function assetPartInfo(mesh, secId) {
      const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material
      const matIsGlass = !!(mat && mat.name && /glass/i.test(mat.name))
      const segs = []
      let o = mesh
      while (o && segs.length < 6) {
        const n = String(o.name || '').replace(/^_+/, '')
        if (n) segs.push(n)
        o = o.parent
      }
      const text = segs
        .join('_')
        .toLowerCase()
        .replace(/(door|window)\d*\s*/g, ' ') // 去掉 proto 前缀（door1_/window1_）
        .replace(/[^a-z_]/g, '_')
        .replace(/_+/g, '_')
      const isDoor = secId === 'door'
      let side = ''
      if (!matIsGlass) {
        if (/left/.test(text)) side = 'left'
        else if (/right/.test(text)) side = 'right'
        else if (/top/.test(text)) side = 'top'
        else if (/bottom/.test(text)) side = 'bottom'
      }
      let role = ''
      if (matIsGlass || /glass/.test(text)) role = 'glass'
      else if (/leaf/.test(text)) role = 'leaf'
      else if (/handle/.test(text)) role = 'handle'
      else if (/hinge/.test(text)) role = 'hinge'
      else if (/lock/.test(text)) role = 'lock'
      else if (/hardware/.test(text)) role = 'hardware'
      else if (/frame/.test(text)) role = 'frame'
      else if (side) role = isDoor ? 'leaf' : 'sash' // 纯 left/right/top → 门扇/窗扇
      else role = 'other'
      const roleKey = role === 'glass' ? 'glass' : role + (side ? '-' + side : '')
      const base = (isDoor
        ? { glass: '玻璃', leaf: '门扇', sash: '门扇', frame: '门框', handle: '把手', hinge: '铰链', lock: '锁具', hardware: '五金', other: segs[0] || '部件' }
        : { glass: '玻璃', leaf: '窗扇', sash: '窗扇', frame: '窗框', handle: '执手', hinge: '铰链', lock: '窗锁', hardware: '五金', other: segs[0] || '部件' })[role] || role
      const sideCn = { left: '左', right: '右', top: '上', bottom: '下' }
      const label = role === 'glass' || !side ? base : (sideCn[side] || side) + base
      const roleOrder = ((isDoor
        ? { frame: 0, leaf: 10, sash: 10, glass: 20, handle: 30, hinge: 40, lock: 50, hardware: 60, other: 90 }
        : { frame: 0, leaf: 10, sash: 10, glass: 20, handle: 30, hinge: 40, lock: 50, hardware: 60, other: 90 })[role] ?? 90)
      const sideOrder = side ? ({ left: 0, right: 1, top: 2, bottom: 3 }[side] ?? 4) : 5
      return { roleKey, label, order: roleOrder + sideOrder / 100 }
    }

    /** 回填某组合体替换素材后的实际子部件清单（无 key = 未替换，UI 回落原始列表） */
    function refreshAssetChildren(key) {
      const h = holders[key]
      if (!h) return
      const secId = h.sectionId
      // 同 key 换素材/重建前：清除旧 asset mesh 记录，避免残留已摘除对象
      assetMeshes.forEach((m) => { if (m.userData && m.userData.key === key) assetMeshes.delete(m) })
      const map = new Map() // roleKey → 子部件条目
      h.group.traverse((o) => {
        if (!o.isMesh) return
        assetMeshes.add(o)
        const info = assetPartInfo(o, secId)
        if (!info) return
        // 逐部件显隐 token（与面板 assetChildren.parts[].id 一致，applyGroupVisibility 据此控制）
        o.userData.partName = key + '|' + info.roleKey
        if (map.has(info.roleKey)) return
        const mat = Array.isArray(o.material) ? o.material[0] : o.material
        map.set(info.roleKey, {
          id: key + '|' + info.roleKey, // 显隐 token（与 mesh.userData.partName 一致）
          name: info.label,
          material: (mat && mat.name) || '',
          order: info.order
        })
      })
      const parts = Array.from(map.values())
        .sort((a, b) => a.order - b.order)
        .map((it) => ({ id: it.id, name: it.name, material: it.material }))
      editorState.assetChildren[key] = { assetId: h.assetId, parts }
    }

    /** 取某组合体 key 的全部替换素材 mesh（assetMeshes 持久记录，含开门/平开时挂到 pivot 的临时子 mesh） */
    function assetMeshesOf(key) {
      const out = []
      assetMeshes.forEach((o) => {
        if (o.isMesh && o.userData && o.userData.key === key) out.push(o)
      })
      return out
    }

    /** 遍历当前全部替换体 mesh（基于 assetMeshes 而非 holder.group：门/窗开合时扇会挂到 pivot，group.traverse 会漏） */
    function eachHolderMesh(fn) {
      assetMeshes.forEach((o) => {
        if (!o.isMesh || !o.userData) return
        const h = holders[o.userData.key]
        if (!h) return
        fn(o, h)
      })
    }

    /** 把某组合体（窗 W1~W8 / 门 door）替换为素材 */
    function replaceWithAsset(key, assetId) {
      const found = findItem(key, catalog)
      if (!root || !found || found.kind !== 'combo') return
      const secId = found.section.id
      if (secId !== 'door' && secId !== 'window') return
      const asset = assetLib.get(assetId)
      if (!asset) return
      if (asset.type !== secId) return // 门/窗素材不可混用（UI 已过滤，双保险）
      // 开门状态下替换门素材：先把门扇挂回原父级并恢复关门姿态，
      // 否则后续按开门时的包围盒计算，会导致新素材位置/尺寸贴合错误
      const wasDoorOpen = key === 'door' && doorOpenState
      if (key === 'door') closeDoorBeforeSwap()
      // 22 door1 等「双扇平开」门若正处于 doorSlides 开合状态 → 先复位（关不回来会残留 pivot 挂旧 mesh）
      if (doorSlides[key]) {
        restoreDoorSlide(key)
        // 若处于 22 门进入室内模式（doorOpenState 复用自 21 门室内标志）→ 一并退出室内
        if (doorOpenState && key !== 'door') exitIndoor()
      }
      // 窗若处于开合状态（素材平开 / 原始推拉）→ 先归位再算包围盒，否则开口位置/尺寸贴合错误
      if (secId === 'window') closeWindowBeforeSwap(key)
      // 整组当前包围盒（原始部件，世界坐标）—— 必须在关门/复位后计算
      const list = meshesOfKey(key)
      if (!list.length) return
      const box = new THREE.Box3()
      list.forEach((m) => box.expandByObject(m))
      if (box.isEmpty()) return
      // 移除旧替换体
      removeHolder(key)
      const holder = buildAssetReplacement(asset, box)
      holder.traverse((o) => {
        if (!o.isMesh) return
        // 归属标记：可拾取 + 高亮 + 分组显隐
        o.userData.key = key
        o.userData.groupId = secId
        o.userData.groupName = found.section.name
        // 材质实例化（proto.clone 共享材质），保证高亮互不影响
        if (Array.isArray(o.material)) o.material = o.material.map((m) => m.clone())
        else if (o.material) o.material = o.material.clone()
        // 素材玻璃层同步当前玻璃质感（透明度/磨砂）
        const mat = Array.isArray(o.material) ? o.material[0] : o.material
        if (mat && mat.name && /glass/i.test(mat.name)) {
          if (!mat.userData) mat.userData = {}
          if (mat.userData._origMap === undefined) mat.userData._origMap = mat.map || null
          applyGlassToMaterial(mat, editorState.glass.opacity, editorState.glass.frosted)
        }
      })
      // 加入场景：优先挂到尺寸编辑 Group，便于后续统一缩放；attach 保持世界变换
      const parent = sizeGroups[key] || root
      parent.attach(holder)
      holders[key] = { group: holder, assetId, sectionId: secId }
      // 隐藏原始部件（记录 replaced 标记，分组显隐时跳过）
      list.forEach((m) => { m.userData.replaced = true; m.visible = false })
      editorState.replacements[key] = assetId
      // 清除同 key 旧素材遗留的逐部件显隐 token，再按新素材结构重建
      Object.keys(editorState.partVisible).forEach((k) => {
        if (k.indexOf(key + '|') === 0) delete editorState.partVisible[k]
      })
      refreshAssetChildren(key) // 回填素材实际子部件 → 右侧「包含子部件」联动 + 逐部件显隐
      refreshKeySize(key)
      // 玻璃信息回填（素材可能无/有玻璃层）+ 重放该组合体独立玻璃设置
      refreshGlassInfo(key)
      applyGlassPerKeyToKey(key, editorState.glassPerKey[key] || null)
      // 替换前门是开着的 → 新素材门也保持开门状态
      if (key === 'door' && wasDoorOpen) reopenDoorPivots()
      applyGroupVisibility() // 素材逐部件/整组显隐与当前显示状态对齐（kv/分组/eye）
      syncHighlight(editorState.selected)
    }

    /** 恢复某组合体的原始部件 */
    function restoreAsset(key) {
      if (!holders[key]) return
      // 开门状态下恢复原始部件：先把素材门扇挂回旧 holder，恢复后再按主模型门重建 pivot
      const wasDoorOpen = key === 'door' && doorOpenState
      if (key === 'door') closeDoorBeforeSwap()
      // 素材窗恢复前：若正在平开先瞬间合扇归位，避免旧 pivot 带走 holder 里的窗扇 mesh
      if (key !== 'door') closeWindowBeforeSwap(key)
      // 素材门（doorSlides 平开）复位：先关 pivot 再移除素材，防止素材门扇 mesh 被残留 pivot 带走
      if (doorSlides[key]) {
        restoreDoorSlide(key)
        // 若处于 22 门进入室内模式（doorOpenState 复用自 21 门室内标志）→ 一并退出室内
        if (doorOpenState && key !== 'door') exitIndoor()
      }
      removeHolder(key)
      delete editorState.replacements[key]
      // 移除素材子部件清单 + 该 key 的逐部件显隐 token → 面板回落原始部件列表
      delete editorState.assetChildren[key]
      Object.keys(editorState.partVisible).forEach((k) => {
        if (k.indexOf(key + '|') === 0) delete editorState.partVisible[k]
      })
      meshesOfKey(key).forEach((m) => { m.userData.replaced = false })
      applyGroupVisibility()
      refreshKeySize(key)
      // 恢复原始部件后：玻璃信息回填 + 重放独立玻璃设置
      refreshGlassInfo(key)
      applyGlassPerKeyToKey(key, editorState.glassPerKey[key] || null)
      if (key === 'door' && wasDoorOpen) reopenDoorPivots()
      syncHighlight(editorState.selected)
    }

    function removeHolder(key) {
      const h = holders[key]
      if (!h) return
      assetMeshes.forEach((m) => { if (m.userData && m.userData.key === key) assetMeshes.delete(m) })
      h.group.removeFromParent()
      delete holders[key]
    }

    /** 回填某键当前实际尺寸（含替换体） */
    function refreshKeySize(key) {
      const b = boxOfKey(key)
      if (!b) return
      editorState.sizes.parts[key] = {
        x: r3(b.max.x - b.min.x),
        y: r3(b.max.y - b.min.y),
        z: r3(b.max.z - b.min.z)
      }
    }

    /* ===== 玻璃质感 ===== */
    /** 判断 mesh 是否为玻璃（门玻璃 Translucent_Glass_Gray / 素材 Glass / 窗玻璃 FrontColor 薄板） */
    function isGlassMesh(m) {
      const mat = Array.isArray(m.material) ? m.material[0] : m.material
      const name = (mat && mat.name) || m.name || ''
      if (/Translucent_Glass_Gray/i.test(name) || /glass/i.test(name)) return true
      if (/FrontColor/i.test(name) && m.userData.groupId === 'window') return true
      return false
    }

    /** 应用玻璃质感到单个材质 */
    function applyGlassToMaterial(mat, opacity, frosted) {
      if (!mat) return
      mat.transparent = true
      mat.opacity = opacity
      mat.depthWrite = false
      if (frosted) {
        mat.roughness = 0.92
        mat.map = getFrostedTexture()
      } else {
        mat.roughness = 0.08
        // 非磨砂：若当前 map 是磨砂纹理则恢复原始 map（记录在 material.userData._origMap）
        if (mat.map && mat.map === getFrostedTexture()) {
          mat.map = (mat.userData && mat.userData._origMap) || null
        }
      }
      mat.needsUpdate = true
    }

    /**
     * 应用玻璃质感。
     * @param {'part'|'all'} scope 作用域：part = 当前选中部件；all = 全部玻璃/门窗 + 替换素材玻璃
     */
    function applyGlassStyle(scope) {
      const g = editorState.glass
      const targets = []
      if (scope === 'all') {
        targets.push(...meshes.filter(isGlassMesh))
      } else {
        const sel = editorState.selected
        if (!sel) return
        if (sel.kind === 'combo') {
          targets.push(...meshesOfKey(sel.item.id).filter(isGlassMesh))
        } else {
          // 子部件（如 Mesh49）：userData.key 是组合体 id，需用 partName 精确匹配
          targets.push(...meshes.filter((m) => m.userData.partName === sel.part.id && isGlassMesh(m)))
        }
      }
      targets.forEach((m) => {
        const mats = Array.isArray(m.material) ? m.material : [m.material]
        mats.forEach((mat) => {
          if (!mat.userData) mat.userData = {}
          if (mat.userData._origMap === undefined) mat.userData._origMap = mat.map || null
          applyGlassToMaterial(mat, g.opacity, g.frosted)
        })
      })
      // 替换素材的玻璃层（材质名含 Glass）同步质感
      eachHolderMesh((o) => {
        const mat = Array.isArray(o.material) ? o.material[0] : o.material
        if (mat && mat.name && /glass/i.test(mat.name)) {
          if (!mat.userData) mat.userData = {}
          if (mat.userData._origMap === undefined) mat.userData._origMap = mat.map || null
          applyGlassToMaterial(mat, g.opacity, g.frosted)
        }
      })
      // 全局设置后重放各组合体独立玻璃设置（per-key 优先，不被全局覆盖）
      applyAllGlassPerKey()
    }

    /* ===== 门窗玻璃独立设置（door / W1~W8 组合体级） ===== */
    /** 素材是否含玻璃层：扫描 assetMeshes（开合状态下扇挂到 pivot 也不会漏） */
    function assetHasGlass(key) {
      return assetMeshesOf(key).some((o) => {
        const mat = Array.isArray(o.material) ? o.material[0] : o.material
        return !!(mat && mat.name && /glass/i.test(mat.name))
      })
    }

    /** 回填某组合体的玻璃信息（UI 据此显示/隐藏独立玻璃设置项） */
    function refreshGlassInfo(key) {
      // main：主模型玻璃（replaced 隐藏的不算）；asset：替换素材玻璃层
      const main = meshesOfKey(key).some((m) => isGlassMesh(m) && !m.userData.replaced)
      const asset = assetHasGlass(key)
      editorState.glassInfo[key] = { main, asset, has: main || asset }
    }

    /** 模型加载后 / 替换 / 恢复后回填全部门窗组合体玻璃信息 */
    function refreshAllGlassInfo() {
      catalog.sections.forEach((s) => {
        if (s.id === 'window' || s.id === 'door') {
          s.items.forEach((it) => refreshGlassInfo(it.id))
        }
      })
    }

    /**
     * 材质独占化：主模型玻璃材质可能被多个组合体共享（GLTFLoader 默认共享实例），
     * 独立设置前 clone 一份并记录原始颜色，避免改一扇窗污染其他共享部件。
     */
    function ownGlassMaterial(m) {
      const wasArray = Array.isArray(m.material)
      const mats = wasArray ? m.material : [m.material]
      const owned = mats.map((mat) => {
        if (!mat) return mat
        if (mat.userData && mat.userData._glassPerKeyOwner) return mat
        const clone = mat.clone()
        if (!clone.userData) clone.userData = {}
        clone.userData = {
          ...(mat.userData || {}),
          _glassPerKeyOwner: true,
          _origColor: mat.color ? mat.color.clone() : new THREE.Color(0xffffff)
        }
        if (clone.userData._origMap === undefined) clone.userData._origMap = mat.map || null
        return clone
      })
      m.material = wasArray ? owned : owned[0]
    }

    /**
     * 应用某组合体（door / W1~W8）的玻璃设置。
     * @param {string} key 组合体 id
     * @param {null|{opacity, frosted, color}} opts null=回落到全局默认；否则 per-key 值
     */
    function applyGlassPerKeyToKey(key, opts) {
      const g = editorState.glass
      const def = { opacity: g.opacity, frosted: g.frosted, color: null }
      const o = opts || def
      const targets = []
      // 主模型玻璃（独占化材质，防共享污染）
      meshesOfKey(key)
        .filter((m) => isGlassMesh(m))
        .forEach((m) => {
          ownGlassMaterial(m)
          targets.push(m)
        })
      // 替换素材的玻璃层（素材材质在 replaceWithAsset 已实例化，直接改；遍历 assetMeshes 兼容开合挂到 pivot 的扇）
      assetMeshesOf(key).forEach((o2) => {
        const mat = Array.isArray(o2.material) ? o2.material[0] : o2.material
        if (mat && mat.name && /glass/i.test(mat.name)) targets.push(o2)
      })
      targets.forEach((m) => {
        const mats = Array.isArray(m.material) ? m.material : [m.material]
        mats.forEach((mat) => {
          if (!mat) return
          if (!mat.userData) mat.userData = {}
          if (mat.userData._origMap === undefined) mat.userData._origMap = mat.map || null
          // 首次接触记录原始颜色（恢复默认时还原，避免素材玻璃被改成纯白）
          if (mat.userData._origColor === undefined) {
            mat.userData._origColor = mat.color ? mat.color.clone() : new THREE.Color(0xffffff)
          }
          applyGlassToMaterial(mat, o.opacity, o.frosted)
          if (o.color) {
            mat.color.set(o.color)
          } else {
            mat.color.copy(mat.userData._origColor)
          }
          mat.needsUpdate = true
        })
      })
    }

    /** 重放所有组合体的 per-key 玻璃设置（全局设置/替换/恢复后调用，per-key 优先） */
    function applyAllGlassPerKey() {
      Object.keys(editorState.glassPerKey).forEach((key) => {
        applyGlassPerKeyToKey(key, editorState.glassPerKey[key])
      })
    }

    /* ===== 墙体贴图 ===== */
    /**
     * 应用墙体贴图。
     * @param {string} key 单部件 id（wall_01 等）；all=true 时忽略
     * @param {string} texId 纹理 id（'original' 恢复；'bz-'/'cz-'/'kz-'/'pm-' 内置；'up-' 已上传）
     * @param {number} density 纹理密度：每米重复次数。例 density=1 → 1 米重复 1 次纹理；
     *   density 越大，砖块/图案越密、越小。每个 wall 按其物理米数换算
     *   tex.repeat = (size_u * density, size_v * density)，保持"每米重复次数"一致。
     *   同时为每面墙 clone 一份 THREE.Texture 实例（基础 canvas 共享），防止多墙共享同一 texture 时 repeat 被互相覆盖。
     * @param {boolean} all 应用到全部墙体
     */
    function applyWallTexture(key, texId, density, all = false) {
      const targets = all
        ? meshes.filter((m) => m.userData.groupId === 'wall')
        : meshes.filter((m) => m.userData.key === key)
      if (!targets.length) return
      const baseTex = texId === 'original' ? null : getWallTexture(texId) || uploadCache[texId] || null
      // 基础纹理统一设置 wrap（基础纹理本身不直接赋给材质，仅供 clone 继承 wrap 模式）
      if (baseTex) {
        baseTex.wrapS = baseTex.wrapT = THREE.RepeatWrapping
        baseTex.repeat.set(1, 1)
      }
      targets.forEach((m) => {
        const mats = Array.isArray(m.material) ? m.material : [m.material]
        // 按墙面的「世界包围盒」米制尺寸换算平铺数。多数墙面立板（厚度最小的一轴为法向），
        // UV 平铺轴取法向以外的两轴；常规立墙 → u=x, v=y；侧面墙（法向±y）→ u=x, v=z。
        // 注意必须用世界盒（expandByObject 含节点自身 scale/root scale/居中平移）：
        // GLB 里墙体几何常以节点 scale≈0.01 挂在场景下，geometry.boundingBox 是「本地几何」尺寸
        // （如 1990），直接×SCALE 会得到 59m 而非真实的 0.6m，导致 repeat 过大、贴图密成一片。
        let uMeter = 1, vMeter = 1
        if (baseTex) {
          const wb = new THREE.Box3().expandByObject(m)
          const sx = wb.max.x - wb.min.x
          const sy = wb.max.y - wb.min.y
          const sz = wb.max.z - wb.min.z
          if (isFinite(sx) && isFinite(sy) && isFinite(sz) && sx + sy + sz > 0) {
            // 找最小轴 = 法向（厚度），剩下两轴为 UV 平面
            if (sy <= sx && sy <= sz) { uMeter = sx; vMeter = sz }
            else if (sz <= sx && sz <= sy) { uMeter = sx; vMeter = sy }
            else { uMeter = sz; vMeter = sy }
            // 极小边兜底
            if (uMeter < 0.001) uMeter = sx || sz || 0.1
            if (vMeter < 0.001) vMeter = sy || 0.1
          }
        }
        // 计算该 mesh 几何自身的 UV 跨度（导出时各墙烘焙了不同的 UV 缩放/偏移，未归一化到 [0,1]）：
        // 同一面墙 U 跨度可能 0..76.77（小侧板）、82..261（中部大板）或 0..1（木饰/水泥隔断）。
        // 若 repeat 只 = 世界尺寸 × 密度，会与已烘焙的 UV 尺度"叠加"，导致大墙面更密、木/水泥墙更稀。
        // 统一做法：repeat = 世界尺寸 × 密度 ÷ UV 跨度，offset = -UV 最小值 × repeat（相位对齐到 0），
        // 使所有墙每米平铺次数一致 = density。
        let uvSpanU = 0, uvSpanV = 0, uvMinU = 0, uvMinV = 0
        if (baseTex && m.geometry && m.geometry.attributes.uv) {
          const arr = m.geometry.attributes.uv.array
          let minU = Infinity, maxU = -Infinity, minV = Infinity, maxV = -Infinity
          for (let k = 0; k < m.geometry.attributes.uv.count; k++) {
            const u = arr[k * 2], v = arr[k * 2 + 1]
            if (u < minU) minU = u
            if (u > maxU) maxU = u
            if (v < minV) minV = v
            if (v > maxV) maxV = v
          }
          uvSpanU = maxU - minU
          uvSpanV = maxV - minV
          uvMinU = minU
          uvMinV = minV
        }
        mats.forEach((mat, i) => {
          if (texId === 'original') {
            mat.map = (m.userData.origMaps && m.userData.origMaps[i]) || null
          } else if (baseTex) {
            // 每面墙克隆独立 texture：每块墙的 repeat/offset 互不影响
            const tex = baseTex.clone()
            tex.wrapS = THREE.RepeatWrapping
            tex.wrapT = THREE.RepeatWrapping
            let ru = uMeter * density
            let rv = vMeter * density
            let ou = 0, ov = 0
            if (uvSpanU > 1e-6) { ru = ru / uvSpanU; ou = -uvMinU * ru }
            if (uvSpanV > 1e-6) { rv = rv / uvSpanV; ov = -uvMinV * rv }
            tex.repeat.set(ru, rv)
            tex.offset.set(ou, ov)
            tex.colorSpace = THREE.SRGBColorSpace
            tex.needsUpdate = true
            mat.map = tex
          }
          mat.needsUpdate = true
        })
        m.userData.wallTexId = texId
      })
      // 回显状态：最近一次应用
      editorState.textures.cur = { key: all ? '' : key, texId, density }
    }

    /** 上传图片 → THREE.Texture（限制最大 1024px，RepeatWrapping + sRGB） */
    function loadUploadedTexture(dataURL) {
      return new Promise((resolve, reject) => {
        const img = new Image()
        img.onload = () => {
          const cv = document.createElement('canvas')
          const max = 1024
          const k = Math.min(1, max / Math.max(img.width, img.height))
          cv.width = Math.max(1, Math.round(img.width * k))
          cv.height = Math.max(1, Math.round(img.height * k))
          cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height)
          const tex = new THREE.CanvasTexture(cv)
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping
          tex.colorSpace = THREE.SRGBColorSpace
          tex.anisotropy = 4
          resolve(tex)
        }
        img.onerror = () => reject(new Error('图片解码失败'))
        img.src = dataURL
      })
    }

    /* ===== 调试钩子 ===== */
    function exposeDebug() {
      if (typeof window !== 'undefined') {
        window.__v3d = {
          meshes, sizeGroups, scene, holders,
          get assetLib() { return assetLib },
          get root() { return root },
          get gridHelper() { return gridHelper },
          get camera() { return camera },
          get renderer() { return renderer },
          getModelBox: () => {
            if (!root) return null
            root.updateMatrixWorld(true)
            const b = getRootBox()
            return { min: b.min.toArray().map((v) => +v.toFixed(3)), max: b.max.toArray().map((v) => +v.toFixed(3)), size: b.getSize(new THREE.Vector3()).toArray().map((v) => +v.toFixed(3)) }
          },
          getKeyBox: (key) => {
            const list = (meshes || []).filter((m) => m.userData.key === key)
            if (!list.length) return null
            const b = new THREE.Box3()
            list.forEach((m) => b.expandByObject(m))
            return { min: b.min.toArray().map((v) => +v.toFixed(3)), max: b.max.toArray().map((v) => +v.toFixed(3)), size: b.getSize(new THREE.Vector3()).toArray().map((v) => +v.toFixed(3)) }
          }
        }
      }
    }
    exposeDebug()

    /* ===== 高亮 ===== */
    function applyHL(mesh, on) {
      const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material]
      mats.forEach((mat) => {
        if (!mat.__baseEmissive) mat.__baseEmissive = mat.emissive ? mat.emissive.clone() : new THREE.Color()
        if (on) {
          mat.emissive.setHex(HL_COLOR)
        } else {
          mat.emissive.copy(mat.__baseEmissive)
        }
        mat.needsUpdate = true
      })
    }

    function highlight(key) {
      meshes.forEach((m) => {
        const on = !!key && (m.userData.key === key || m.name === key)
        applyHL(m, on)
      })
      // 替换素材的 mesh 同样参与高亮
      eachHolderMesh((o) => {
        applyHL(o, !!key && o.userData.key === key)
      })
    }

    /** 由 selected 结构解析高亮键：组合体 → item.id；单部件 → part.id */
    function syncHighlight(sel) {
      let key = null
      if (sel) {
        key = sel.kind === 'combo' && sel.item ? sel.item.id : (sel.part ? sel.part.id : null)
      }
      highlight(key)
    }

    /* ===== 拾取 / 触屏手势（双击展开操作面板；双指捏合 = 默认缩放整个模型视角/相机） ===== */
    const ptrs = new Map() // pointerId → { x, y }
    let sawMulti = false // 本次触点序列是否出现过双指（双指缩放结束时不当点击）
    let lastDown = null // 单指按下记录 { t, key, x, y }，用于双击判定
    let suppressUntil = 0 // 双击已处理：短暂屏蔽本次抬起产生的重复拾取/浮动按钮

    /** 屏幕坐标 → 命中部件 key（原始 + 替换素材 mesh 均参与） */
    function hitKeyAt(clientX, clientY) {
      if (!renderer) return ''
      const rect = renderer.domElement.getBoundingClientRect()
      const px = ((clientX - rect.left) / rect.width) * 2 - 1
      const py = -((clientY - rect.top) / rect.height) * 2 + 1
      raycaster.setFromCamera(new THREE.Vector2(px, py), camera)
      const targets = meshes.slice()
      eachHolderMesh((o) => targets.push(o))
      const hits = raycaster.intersectObjects(targets, false).filter((h) => h.object && h.object.visible)
      return hits.length ? (hits[0].object.userData.key || '') : ''
    }

    function onPointerDown(e) {
      ptrs.set(e.pointerId, { x: e.clientX, y: e.clientY })
      if (ptrs.size === 2) sawMulti = true
      // 仅主指针且是第一个触点：记录点击起点并做双击判定
      if (e.isPrimary && ptrs.size === 1) {
        downPos = { x: e.clientX, y: e.clientY }
        detectDoubleDown(e)
      }
    }

    function onPointerMove(e) {
      if (ptrs.has(e.pointerId)) ptrs.set(e.pointerId, { x: e.clientX, y: e.clientY })
    }

    function onPointerUp(e) {
      if (ptrs.has(e.pointerId)) {
        ptrs.delete(e.pointerId)
        if (ptrs.size === 0) sawMulti = false
      }
      if (!e.isPrimary) return
      // 双指（相机缩放）结束、或双击已处理 → 本次抬起不算单击
      if (sawMulti || Date.now() < suppressUntil) {
        downPos = null
        return
      }
      if (!downPos) return
      const dx = e.clientX - downPos.x
      const dy = e.clientY - downPos.y
      downPos = null
      if (dx * dx + dy * dy > 36) return // 拖拽/旋转不算点击
      pick(e)
    }

    function onPointerCancel(e) {
      if (ptrs.has(e.pointerId)) {
        ptrs.delete(e.pointerId)
        if (ptrs.size === 0) sawMulti = false
      }
      if (e.isPrimary) downPos = null
    }

    /**
     * 双击判定放在「第二次按下」时执行：只要两次按下时间/距离接近（420ms / 48px），
     * 立即展开操作面板 —— 不依赖第二次抬起是否落在画布上
     * （单击门/窗会在第一次点击处弹出浮动按钮，可能拦截第二次的 click/pointerup）。
     */
    function detectDoubleDown(e) {
      const now = Date.now()
      const hit = hitKeyAt(e.clientX, e.clientY)
      if (lastDown && now - lastDown.t <= 420 &&
          Math.hypot(e.clientX - lastDown.x, e.clientY - lastDown.y) <= 48) {
        // 第二次命中取 hit，否则沿用第一次的 key（第二次可能点在浮动按钮上）
        const key = hit || lastDown.key
        lastDown = null
        if (key) {
          suppressUntil = now + 700 // 双击已处理：本组抬起不再当普通单击/浮动按钮
          openPartPanel(key)
        }
      } else {
        lastDown = hit ? { t: now, key: hit, x: e.clientX, y: e.clientY } : null
      }
    }

    /** 双击部件 → 选中并展开其操作面板（移动端=底部抽屉；桌面端=右侧属性栏）。
     *  非ce 延迟 120ms 触发：等本次双击的指针抬起序列完全结束再展开，
     *  避免“展开瞬间遮罩出现 → 同一次手势的抬起被判定为点遮罩 → 面板闪现即关”。 */
    function openPartPanel(key) {
      const found = findItem(key, catalog)
      if (!found) return
      if (found.kind === 'combo') selectItem(found.section, found.item)
      else selectPart(found.section, found.item, found.part)
      hideDoorToggleBtn()
      hideDoorSlideToggleBtn()
      hideWinToggleBtn()
      if (!roofIsHidden()) hideRoofToggleBtn()
      editorState.tab = 'props'
      setTimeout(() => {
        editorState.panelOpen.nonce++
      }, 120)
    }

    function pick(e) {
      const key = hitKeyAt(e.clientX, e.clientY)
      if (!key) {
        hideDoorToggleBtn()
        hideDoorSlideToggleBtn()
        hideWinToggleBtn()
        if (!roofIsHidden()) hideRoofToggleBtn()
        clearSelection()
        return ''
      }
      const found = findItem(key, catalog)
      if (!found) {
        hideDoorToggleBtn()
        hideDoorSlideToggleBtn()
        hideWinToggleBtn()
        if (!roofIsHidden()) hideRoofToggleBtn()
        clearSelection()
        return ''
      }
      if (found.kind === 'combo') selectItem(found.section, found.item)
      else selectPart(found.section, found.item, found.part)
      // 点击门 → 在点击位置弹出「开门/关门」按钮，点按钮才执行开合（不再直接开关门）
      if (found.kind === 'combo' && found.section.id === 'door') {
        if (isSlidingDoor(found.item)) showDoorSlideToggleBtn(e, key)
        else if (isFrenchDoor(found.item)) showFrenchDoorToggleBtn(e, key)
        else if (features.doorOpen) showDoorToggleBtn(e)
      }
      // 点击窗 → 同样只弹「开窗/关窗」按钮，点按钮才开合（不再点击即开窗）
      else if (found.kind === 'combo' && found.section.id === 'window') showWindowToggleBtn(e, key)
      // 点击屋顶 → 弹「打开屋顶/关闭屋顶」按钮
      else if (found.kind === 'combo' && found.section.id === 'roof' && features.roof) showRoofToggleBtn(e)
      return key
    }

    /* ===== 门开合浮动按钮（点击门位置弹出，点按钮执行开/关门） ===== */
    let doorBtnEl = null // 当前门操作浮动按钮
    function showDoorToggleBtn(e) {
      hideDoorToggleBtn()
      hideDoorSlideToggleBtn() // 同一时刻只保留一个开合浮动按钮
      hideWinToggleBtn() // 门/窗/屋顶浮动按钮互斥（屋顶隐藏时保留其恢复按钮）
      if (!roofIsHidden()) hideRoofToggleBtn()
      const btn = document.createElement('button')
      btn.className = 'v3d-door-btn'
      btn.textContent = doorOpenState ? '🚪 关门' : '🚪 开门'
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation()
        hideDoorToggleBtn()
        toggleDoor()
      })
      const rect = rootRef.value.getBoundingClientRect()
      btn.style.left = (e.clientX - rect.left) + 'px'
      btn.style.top = (e.clientY - rect.top) + 'px'
      rootRef.value.appendChild(btn)
      doorBtnEl = btn
    }
    function hideDoorToggleBtn() {
      if (doorBtnEl) {
        if (doorBtnEl.parentNode) doorBtnEl.parentNode.removeChild(doorBtnEl)
        doorBtnEl = null
      }
    }

    /* ===== 双扇平开门浮动按钮（点击 door1 位置弹出，点按钮才开/关门） ===== */
    let doorSlideBtnEl = null
    /** 某门当前是否处于打开状态 */
    function doorSlideIsOpen(key) {
      return doorSlides[key] && !!doorSlides[key].open
    }
    function showDoorSlideToggleBtn(e, key) {
      hideDoorToggleBtn() // 同一时刻只保留一个开合浮动按钮
      hideDoorSlideToggleBtn()
      hideWinToggleBtn()
      if (!roofIsHidden()) hideRoofToggleBtn()
      const open = doorSlideIsOpen(key)
      const btn = document.createElement('button')
      btn.className = 'v3d-door-btn'
      btn.textContent = open ? '🚪 关门' : '🚪 开门'
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation()
        hideDoorSlideToggleBtn()
        toggleDoorSlide(key, !doorSlideIsOpen(key))
      })
      const rect = rootRef.value.getBoundingClientRect()
      btn.style.left = (e.clientX - rect.left) + 'px'
      btn.style.top = (e.clientY - rect.top) + 'px'
      rootRef.value.appendChild(btn)
      doorSlideBtnEl = btn
    }
    function hideDoorSlideToggleBtn() {
      if (doorSlideBtnEl) {
        if (doorSlideBtnEl.parentNode) doorSlideBtnEl.parentNode.removeChild(doorSlideBtnEl)
        doorSlideBtnEl = null
      }
    }

    /* ===== 法式门浮动按钮（点击门1/2/3 弹出，点按钮才执行开/关） ===== */
    function showFrenchDoorToggleBtn(e, key) {
      hideDoorToggleBtn()
      hideDoorSlideToggleBtn()
      hideWinToggleBtn()
      if (!roofIsHidden()) hideRoofToggleBtn()
      const fd = frenchDoorPivots[key] || buildFrenchDoorPivot(key)
      const open = fd ? fd.open : false
      const btn = document.createElement('button')
      btn.className = 'v3d-door-btn'
      btn.textContent = open ? '🚪 关门' : '🚪 开门'
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation()
        hideFrenchDoorToggleBtn()
        toggleFrenchDoor(key)
      })
      const rect = rootRef.value.getBoundingClientRect()
      btn.style.left = (e.clientX - rect.left) + 'px'
      btn.style.top = (e.clientY - rect.top) + 'px'
      rootRef.value.appendChild(btn)
      frenchDoorBtnEl = btn
    }
    function hideFrenchDoorToggleBtn() {
      if (frenchDoorBtnEl) {
        if (frenchDoorBtnEl.parentNode) frenchDoorBtnEl.parentNode.removeChild(frenchDoorBtnEl)
        frenchDoorBtnEl = null
      }
    }

    /* ===== 窗开合浮动按钮（点击窗位置弹出，点按钮才开/关窗） =====
     * 行为随窗当前状态自动切换：
     *   - 整窗被替换成素材且素材含 left/right 窗扇 → 素材窗「向外平开」；
     *   - 未替换的原始推拉窗 → 保持原有滑动开合（默认右滑开）。
     */
    let winBtnEl = null
    function hideWinToggleBtn() {
      if (winBtnEl) {
        if (winBtnEl.parentNode) winBtnEl.parentNode.removeChild(winBtnEl)
        winBtnEl = null
      }
    }
    /** 某窗当前是否处于开的状态（素材平开 / 原始外开平开 / 原始推拉任一） */
    function windowIsOpenAny(key) {
      if (windowSwingKey === key) return true
      const np = nativeWinSwingPivots[key]
      if (np && np.open) return true
      const d = editorState.windowSlide.key === key ? editorState.windowSlide.dir : ''
      return !!d
    }
    function showWindowToggleBtn(e, key) {
      hideDoorToggleBtn() // 同一时刻只保留一个开合浮动按钮
      hideDoorSlideToggleBtn()
      hideWinToggleBtn()
      if (!roofIsHidden()) hideRoofToggleBtn()
      const open = windowIsOpenAny(key)
      const isSwingAsset = !!windowAssetSashMeshes(key)
      const fnd = findItem(key, catalog)
      const isSwingNative = !isSwingAsset && fnd && fnd.kind === 'combo' && isSwingOutWindow(fnd.item)
      // 固定窗（非 5 件式原始推拉/外开、也未替换素材）无可开合动作 → 不弹按钮
      if (!isSwingAsset && !isSwingNative) {
        if (!fnd || fnd.kind !== 'combo' || (fnd.item.parts || []).length !== 5) return
      }
      const btn = document.createElement('button')
      btn.className = 'v3d-door-btn'
      btn.textContent = open ? '🪟 关窗' : '🪟 开窗'
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation()
        hideWinToggleBtn()
        if (isSwingAsset) {
          applyWindowOpen(key, !open)
        } else if (isSwingNative) {
          toggleNativeWindowSwing(key, !open)
        } else {
          const d = editorState.windowSlide.key === key ? editorState.windowSlide.dir : ''
          toggleWindow(key, d ? '' : 'right')
        }
      })
      const rect = rootRef.value.getBoundingClientRect()
      btn.style.left = (e.clientX - rect.left) + 'px'
      btn.style.top = (e.clientY - rect.top) + 'px'
      rootRef.value.appendChild(btn)
      winBtnEl = btn
    }

    /* ===== 屋顶开合浮动按钮（点击屋顶弹出；「打开屋顶」= 隐藏屋顶部件，再点恢复显示） =====
     * 语义（2026-09-03 用户确认）：打开屋顶 = 把屋顶组件隐藏（便于从上方查看室内布局），
     * 不做向上移动。屋顶隐藏后本体不可拾取 → 恢复按钮原地保留，直到点「关闭屋顶」恢复。 */
    let roofBtnEl = null
    /** 屋顶当前是否处于「打开（隐藏）」状态（与右侧面板眼睛按钮共用 keyVisible.roof） */
    function roofIsHidden() {
      const kv = editorState.keyVisible || {}
      const vis = (editorState.display && editorState.display.groups) || {}
      return kv['roof'] === false || vis['roof'] === false
    }
    function syncRoofBtnText() {
      if (roofBtnEl) roofBtnEl.textContent = roofIsHidden() ? '🏠 关闭屋顶' : '🏠 打开屋顶'
    }
    function showRoofToggleBtn(e) {
      hideDoorToggleBtn() // 屋顶/门/窗浮动按钮互斥（屋顶已隐藏时仍保留恢复按钮）
      hideDoorSlideToggleBtn()
      hideWinToggleBtn()
      if (!roofIsHidden()) hideRoofToggleBtn()
      const btn = document.createElement('button')
      btn.className = 'v3d-door-btn'
      btn.textContent = roofIsHidden() ? '🏠 关闭屋顶' : '🏠 打开屋顶'
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation()
        toggleRoof()
      })
      const rect = rootRef.value.getBoundingClientRect()
      btn.style.left = (e.clientX - rect.left) + 'px'
      btn.style.top = (e.clientY - rect.top) + 'px'
      rootRef.value.appendChild(btn)
      roofBtnEl = btn
    }
    function hideRoofToggleBtn() {
      if (roofBtnEl) {
        if (roofBtnEl.parentNode) roofBtnEl.parentNode.removeChild(roofBtnEl)
        roofBtnEl = null
      }
    }

    /** 屋顶开合主逻辑：切换 keyVisible.roof（watch → applyGroupVisibility 应用显隐）。
     *  打开（隐藏）后自动飞到室内正上方俯视室内；恢复显示时退出俯视模式。 */
    function toggleRoof() {
      if (!root || !meshes.length) return
      const hidden = roofIsHidden()
      editorState.keyVisible['roof'] = hidden ? true : false
      if (roofIsHidden()) {
        // —— 屋顶已隐藏：进入「俯视室内」——
        if (roofBtnEl) syncRoofBtnText()
        if (!roomBox) roomBox = computeRoomBox()
        if (roomBox) {
          const c = roomBox.getCenter(new THREE.Vector3())
          c.y = Math.min(Math.max(c.y, 0.28), 0.45) // 俯视基准（内腔中部高度）
          roofLookCenter = c.clone()
          roofOverlook = true
          flyTo(c, c.clone().add(new THREE.Vector3(0, 1.8, 0)), 900)
        }
      } else {
        // —— 屋顶恢复显示：退出俯视模式 → 相机回正视角（门面/默认视角） ——
        roofOverlook = false
        roofLookCenter = null
        wasInsideRoom = false
        relaxRoomControls()
        if (roofBtnEl) hideRoofToggleBtn()
        setView('front')
      }
    }

    /* ===== 门开合（点击门 → 开门动画 → 相机进入室内） ===== */
    // 门扇部件：door1 铰链在 z 负端（Mesh22/23）→ dir +1；door2 铰链在 z 正端（Mesh29/30）→ dir -1
    // leaf = 跟随门扇旋转的全部部件：门扇板 + 玻璃 + 门框柱（Mesh19/26）+ 把手（Mesh20/21、Mesh27/28）；
    // hinge 为固定旋转轴（铰链/锁座），不随门扇旋转
    const DOOR_LEAVES = [
      { hinge: ['Mesh22', 'Mesh23'], leaf: ['Mesh19', 'Mesh20', 'Mesh21', 'Mesh24', 'Mesh25'], dir: 1 },
      { hinge: ['Mesh29', 'Mesh30'], leaf: ['Mesh26', 'Mesh27', 'Mesh28', 'Mesh31', 'Mesh32'], dir: -1 }
    ]
    const DOOR_OPEN_RAD = THREE.MathUtils.degToRad(100)
    let doorOpenState = false
    let doorPivots = null

    function doorMeshesOf(names) {
      return names.map((n) => meshes.find((m) => m.userData.partName === n)).filter(Boolean)
    }

    /** 构建门扇 pivot（每扇一个，挂到 root，位置 = 铰链中心，保持门扇世界变换） */
    function buildDoorPivots() {
      const pivots = []
      DOOR_LEAVES.forEach((cfg) => {
        const hinges = doorMeshesOf(cfg.hinge)
        if (!hinges.length) return
        const b = new THREE.Box3()
        hinges.forEach((m) => b.expandByObject(m))
        const c = b.getCenter(new THREE.Vector3())
        const g = new THREE.Group()
        g.position.copy(root.worldToLocal(c))
        root.add(g)
        const leaves = doorMeshesOf(cfg.leaf)
        const saved = leaves.map((m) => ({ m, parent: m.parent }))
        leaves.forEach((m) => g.attach(m)) // attach 保持世界变换
        pivots.push({ g, dir: cfg.dir, saved })
      })
      return pivots
    }

    /**
     * 门被替换素材时：素材门为双开门（left/right 门扇 + 同侧把手），
     * 门扇绕各自外侧铰链旋转（frame 固定）。方向规律与主模型一致：
     *   铰链在 z 最小端（外侧）→ dir=+1；铰链在 z 最大端 → dir=-1（保证门扇朝室内 +X 打开）。
     * @param {string} key 门组合体 key（默认 'door' 兼容 21；22 door1 等素材门传入对应 key）
     */
    function buildHolderDoorPivot(key = 'door') {
      const holder = holders[key]
      if (!holder) return []
      // 关键：holder 刚 attach 到 root，matrixWorld 可能过期 → 先更新再算铰链
      root.updateMatrixWorld(true)
      // 语义名：多 primitive 节点的子 Mesh 名是 Mesh031 等，语义名在父级 Group（如 door2_left_door_handle）
      const semanticName = (o) => {
        const self = (o.name || '').trim().toLowerCase()
        if (/frame|leaf|handle|left|right/.test(self)) return self
        const p = o.parent && o.parent !== holder.group ? (o.parent.name || '').trim().toLowerCase() : ''
        return p || self
      }
      // 左右扇组：每组 = 门扇(leaf) + 把手(handle)，都要随门扇旋转；frame 固定不参与
      const groups = { left: [], right: [] }
      holder.group.traverse((o) => {
        if (!o.isMesh) return
        const n = semanticName(o)
        if (/frame/.test(n)) return
        if (/left/.test(n)) groups.left.push(o)
        else if (/right/.test(n)) groups.right.push(o)
      })
      const groupList = [groups.left, groups.right].filter((g) => g.length)
      if (!groupList.length) {
        // 兜底：无 left/right 命名 → 旋转整个素材门
        const g = new THREE.Group()
        const b = new THREE.Box3().setFromObject(holder.group)
        const c = b.getCenter(new THREE.Vector3())
        g.position.copy(root.worldToLocal(c))
        root.add(g)
        const saved = [{ m: holder.group, parent: holder.group.parent }]
        g.attach(holder.group)
        return [{ g, dir: 1, saved }]
      }
      // 按语义（left/right）排序仅用于保持分组稳定；铰链端不依赖 left/right 语义，
      // 而是按门扇世界包围盒的 z 外侧端动态判定（见下）——素材可能被 buildAssetReplacement
      // 翻转（取决于开口 center.x 正负），left 不固定对应 z 最小端
      groupList.sort((a, b) => {
        const aLeft = a.some((m) => /left/.test(semanticName(m))) ? -1 : 1
        const bLeft = b.some((m) => /left/.test(semanticName(m))) ? -1 : 1
        return aLeft - bLeft
      })
      // 铰链端动态判定：不再假设素材是否被 buildAssetReplacement 翻转（是否翻转取决于
      // 开口中心 x 正负），而是用每扇门扇的世界包围盒 z 外侧端作为铰链竖边 —— 无论素材
      // 翻转与否都能落在真实铰链边上，且比门框 z 极值更贴合（门扇比门框窄时轴不偏移）
      const doorBox = boxOfKey(key)
      const doorCenter = doorBox.getCenter(new THREE.Vector3())
      const leafBoxes = groupList.map((list) => {
        const b = new THREE.Box3()
        list.forEach((m) => b.expandByObject(m))
        return b
      })
      // z 大端扇索引；单扇（只有 left 或 right）时按相对门洞中心判断
      let zMaxSideIdx
      if (leafBoxes.length === 1) {
        zMaxSideIdx = leafBoxes[0].getCenter(new THREE.Vector3()).z > doorCenter.z ? 0 : -1
      } else {
        const zMids = leafBoxes.map((b) => b.getCenter(new THREE.Vector3()).z)
        zMaxSideIdx = zMids[0] >= zMids[1] ? 0 : 1
      }
      const pivots = []
      leafBoxes.forEach((b, i) => {
        const list = groupList[i]
        const isZMaxSide = zMaxSideIdx === -1 ? false : i === zMaxSideIdx
        // 铰链 = 门扇 z 外侧端竖边：x 用门扇厚度中心、y 用门洞竖向中心
        const bc = b.getCenter(new THREE.Vector3())
        const hinge = new THREE.Vector3(bc.x, doorCenter.y, isZMaxSide ? b.max.z : b.min.z)
        const g = new THREE.Group()
        g.position.copy(root.worldToLocal(hinge))
        root.add(g)
        const saved = list.map((m) => ({ m, parent: m.parent }))
        list.forEach((m) => {
          // 素材 mesh 携带非均匀 scale（buildAssetReplacement 的 kx/ky/kz 独立缩放）。
          // attach 到 pivot 后 rotation.y 与非均匀 scale 叠加会扭曲门扇 → 先把 scale bake 进 geometry 再 attach
          if (m.scale.x !== 1 || m.scale.y !== 1 || m.scale.z !== 1) {
            const geo = m.geometry.clone()
            geo.scale(m.scale.x, m.scale.y, m.scale.z)
            m.geometry = geo
            m.scale.set(1, 1, 1)
          }
          g.attach(m)
        })
        // 开门方向与主模型门1/门2 约定一致：铰链在 z 小端 → dir=+1，z 大端 → dir=-1，均朝室内 +X 打开
        pivots.push({ g, dir: isZMaxSide ? -1 : 1, saved })
      })
      return pivots
    }

    function doorTargetPivots() {
      if (holders['door']) return buildHolderDoorPivot()
      return buildDoorPivots()
    }

    /** 开门状态下切换门部件（替换素材/恢复原始）前：先把门扇挂回原父级，
     *  否则旧门扇仍挂在旧 pivot 上，被 removeHolder 移出后残留 */
    function closeDoorBeforeSwap() {
      if (!doorOpenState) return
      if (doorPivots) {
        restorePivots(doorPivots)
        doorPivots = null
      }
      doorOpenState = false
      editorState.door.open = false
      // 相机约束一并释放（替换门/恢复原始门时相机应回常规模式）
      roomBox = null
      wasInsideRoom = false
      relaxRoomControls()
    }

    /** 门素材替换/恢复后：重建 pivot 并瞬间置为开门角度（调用方需先确认替换前为开门状态） */
    function reopenDoorPivots() {
      doorPivots = doorTargetPivots()
      if (!doorPivots.length) return
      doorPivots.forEach((p) => { p.g.rotation.y = p.dir * DOOR_OPEN_RAD })
      doorOpenState = true
      editorState.door.open = true
      // 重建后内腔约束基准（若此前相机在室内，切换素材后仍能继续防穿墙）
      if (!roomBox) roomBox = computeRoomBox()
    }

    /** 开门/关门动画（tween pivot.rotation.y = dir * angle） */
    function tweenDoor(pivots, open, done) {
      if (!pivots.length) { if (done) done(); return }
      cancelAnimationFrame(doorAnim)
      const t0 = performance.now()
      const dur = 900
      const ease = (k) => (k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2)
      const step = (t) => {
        const k = Math.min((t - t0) / dur, 1)
        const e = ease(k)
        const ang = open ? DOOR_OPEN_RAD * e : DOOR_OPEN_RAD * (1 - e)
        pivots.forEach((p) => { p.g.rotation.y = p.dir * ang })
        if (k < 1) doorAnim = requestAnimationFrame(step)
        else if (done) done()
      }
      doorAnim = requestAnimationFrame(step)
    }

    /** 关门后：门扇 mesh 挂回原父级、移除 pivot */
    function restorePivots(pivots) {
      pivots.forEach((p) => {
        p.saved.forEach(({ m, parent }) => { if (parent) parent.attach(m) })
        p.g.removeFromParent()
      })
    }

    /* ===== 室内相机约束 ===== */
    const clampV = (v, lo, hi) => Math.min(Math.max(v, lo), hi)

    /**
     * 由墙体（groupId='wall'）与屋顶实测推导室内内腔包围盒（世界坐标）。
     * 基准说明：
     *  - X 向厚板（薄轴 X）且板心 x<0 → 提供内腔 x 下限（取各板 max.x 的最大值 = 最靠内的面）；
     *    x>0 → x 上限（取各板 min.x 最小值）。
     *  - Z 向厚板同理给出 z 下限/上限（集装箱长墙沿 Z，端墙沿 X）。
     *  - 天花板 = 屋顶部件下沿 - 0.03（留镜头余量）；地板下沿 0.02。
     */
    function computeRoomBox() {
      if (!root) return null
      root.updateMatrixWorld(true)
      const walls = meshes.filter((m) => m.userData.groupId === 'wall')
      if (!walls.length) return null
      const xMinIn = [], xMaxIn = [], zMinIn = [], zMaxIn = []
      walls.forEach((m) => {
        const b = new THREE.Box3().setFromObject(m)
        const s = b.getSize(new THREE.Vector3())
        const c = b.getCenter(new THREE.Vector3())
        if (s.x < 0.12 && s.x <= s.z) {
          if (c.x < 0) xMinIn.push(b.max.x)
          else xMaxIn.push(b.min.x)
        } else if (s.z < 0.12) {
          if (c.z < 0) zMinIn.push(b.max.z)
          else zMaxIn.push(b.min.z)
        }
      })
      if (!xMinIn.length || !xMaxIn.length || !zMinIn.length || !zMaxIn.length) {
        // 兜底：墙体识别不完整时按整箱内缩近似内腔
        const gb = getRootBox()
        if (!gb) return null
        const b2 = gb.clone()
        b2.min.x += 0.1; b2.max.x -= 0.1
        b2.min.z += 0.1; b2.max.z -= 0.1
        b2.min.y = 0.02
        b2.max.y = Math.max(0.35, b2.max.y - 0.1)
        return b2
      }
      const box = new THREE.Box3(
        new THREE.Vector3(Math.max(...xMinIn), 0.02, Math.max(...zMinIn)),
        new THREE.Vector3(Math.min(...xMaxIn), 0.62, Math.min(...zMaxIn))
      )
      // 天花板 = 屋顶（key='roof'）下沿
      const roofs = meshes.filter((m) => m.userData.key === 'roof')
      if (roofs.length) {
        let top = Infinity
        roofs.forEach((m) => {
          const bb = new THREE.Box3().setFromObject(m)
          if (bb.min.y < top) top = bb.min.y
        })
        if (isFinite(top)) box.max.y = top - 0.03
      }
      if (box.max.y - box.min.y < 0.2) box.max.y = box.min.y + 0.35
      return box
    }

    function cameraInsideRoom(p, b) {
      if (!b) return false
      return p.x > b.min.x - 0.1 && p.x < b.max.x + 0.1 &&
             p.z > b.min.z - 0.1 && p.z < b.max.z + 0.1 &&
             p.y > b.min.y - 0.1 && p.y < b.max.y + 0.1
    }

    /** 进入室内后收紧 OrbitControls：禁止平移/缩放（第一人称原地转头），距离贴近眼位 */
    function tightenRoomControls() {
      if (!controls) return
      controls.enablePan = false
      controls.enableZoom = false
      controls.minDistance = 0.06
      controls.maxDistance = 0.9
    }

    /** 离开内腔后恢复常规 OrbitControls */
    function relaxRoomControls() {
      if (!controls) return
      controls.enablePan = true
      controls.enableZoom = true
      controls.minDistance = 0.5
      controls.maxDistance = 20
    }

    /**
     * 每帧执行（门开着 或 屋顶俯视室内模式 且相机在对应范围时）：
     *  - 门第一人称：把相机坐标钳制在室内 + OrbitControls 目标放到视线前方 ~0.45m（原地转头，避免绕远处做大半径公转穿墙）
     *  - 屋顶俯视室内：屋顶已隐藏，相机在室内正上方 —— 只钳制水平/高度（顶部开放），目标锁定室中心（俯视俯瞰室内布局）
     */
    function enforceIndoorCamera() {
      if (!roomBox || flyRunning) return
      const p = camera.position
      const b = roomBox
      if (roofOverlook) {
        // ===== 屋顶俯视室内（顶部开放，允许相机在室内高度范围） =====
        const insideTop = p.x > b.min.x - 0.1 && p.x < b.max.x + 0.1 &&
                          p.z > b.min.z - 0.1 && p.z < b.max.z + 0.1 &&
                          p.y > -0.1 && p.y < 3.2
        if (insideTop !== wasInsideRoom) {
          wasInsideRoom = insideTop
          if (insideTop) {
            controls.enablePan = false
            controls.enableZoom = true
            controls.minDistance = 0.3
            controls.maxDistance = 2.6
          } else relaxRoomControls()
        }
        if (!insideTop) return
        const m = 0.06
        p.x = clampV(p.x, b.min.x + m, b.max.x - m)
        p.z = clampV(p.z, b.min.z + m, b.max.z - m)
        p.y = clampV(p.y, 0.2, 3.0)
        if (roofLookCenter) controls.target.copy(roofLookCenter)
        return
      }
      if (!doorOpenState) {
        if (wasInsideRoom) { wasInsideRoom = false; relaxRoomControls() }
        return
      }
      // ===== 门第一人称（内腔） =====
      const inside = cameraInsideRoom(p, b)
      if (inside !== wasInsideRoom) {
        if (inside) tightenRoomControls()
        else relaxRoomControls()
        wasInsideRoom = inside
      }
      if (!inside) return
      const m = 0.06
      p.x = clampV(p.x, b.min.x + m, b.max.x - m)
      p.z = clampV(p.z, b.min.z + m, b.max.z - m)
      p.y = clampV(p.y, 0.08, Math.max(b.min.y + 0.08, b.max.y - 0.18))
      const fwd = new THREE.Vector3()
      camera.getWorldDirection(fwd)
      fwd.y = 0
      if (fwd.lengthSq() > 1e-6) fwd.normalize()
      const eye = p.clone()
      const t = eye.clone().addScaledVector(fwd, 0.45)
      controls.target.copy(t)
    }

    /** 相机进入室内：基准 = 门洞中心向室内 (+X) 偏移 0.35m 为初始位置、前方 1m 为视线目标；
     *  初始位置先强制钳制到内腔，保证起点必在室内。
     *  @param {string} doorKey 门组合体 key（21 合并门 'door'；22 独立门 'door1' 等） */
    function enterRoom(doorKey = 'door') {
      const b = boxOfKey(doorKey)
      if (!b) return
      const c = b.getCenter(new THREE.Vector3())
      const enterPos = new THREE.Vector3(c.x + 0.35, Math.max(c.y, 0.25), c.z)
      const look = new THREE.Vector3(c.x + 1.0, c.y, c.z)
      roomBox = computeRoomBox()
      if (roomBox) {
        const m = 0.08
        enterPos.x = clampV(enterPos.x, roomBox.min.x + m, roomBox.max.x - m)
        enterPos.z = clampV(enterPos.z, roomBox.min.z + m, roomBox.max.z - m)
        enterPos.y = clampV(enterPos.y, roomBox.min.y + 0.06, Math.max(roomBox.min.y + 0.06, roomBox.max.y - 0.18))
        look.x = clampV(look.x, roomBox.min.x + 0.02, roomBox.max.x - 0.02)
        look.z = clampV(look.z, roomBox.min.z + 0.02, roomBox.max.z - 0.02)
      }
      flyTo(look, enterPos, 1000)
    }

    /** 退出室内第一人称：清室内状态、恢复常规 OrbitControls、相机退回模型正面视角 */
    function exitIndoor() {
      doorOpenState = false
      roomBox = null
      wasInsideRoom = false
      relaxRoomControls()
      setView('front')
    }

    function toggleDoor() {
      hideDoorToggleBtn() // 执行开合后浮动按钮消失
      if (!features.doorOpen) return // 当前模型未启用原生门开合（如模型 22 的 4 组门）
      if (!root || !meshes.length) return
      if (doorOpenState) {
        // 关门 → 相机退回门外
        editorState.door.open = false
        const pivots = doorPivots || doorTargetPivots()
        tweenDoor(pivots, false, () => {
          restorePivots(pivots)
          doorPivots = null
          doorOpenState = false
          roomBox = null
          wasInsideRoom = false
          relaxRoomControls()
          setView('front')
        })
      } else {
        editorState.door.open = true
        // 通过门进入室内：让位门的第一人称模式（若此前处于屋顶俯视模式则退出）
        roofOverlook = false
        roofLookCenter = null
        doorPivots = doorTargetPivots()
        if (!doorPivots.length) return
        doorOpenState = true
        tweenDoor(doorPivots, true, () => enterRoom())
      }
    }

    /* ===== 窗户滑动开合（点击窗 → 窗扇滑动，支持向左/向右两个方向） ===== */
    // 每扇窗 5 部件 = 外框 ×1（固定）+ 窗扇 ×2（框+玻璃，可滑）。
    // 滑动轴 = 外框宽度最大的水平轴：X 端墙窗（W1/W2/W7/W8）沿 Z 滑；Z 端墙窗（W3~W6）沿 X 滑
    // 方向：dir='left' 右扇向左滑至与左扇重合；dir='right' 左扇向右滑至与右扇重合
    const windowSlides = {}   // key → { g1, g2, axis, dist, dir: ''|'left'|'right' }
    const windowAnims = {}   // key → animId

    function windowSlideAxis(key) {
      // 用外框（体积最大部件）的水平尺寸判断滑动轴：窗扇沿外框更长的水平轴排列 → 滑动轴 = 尺寸更大的一轴
      const found = findItem(key, catalog)
      if (!found || found.kind !== 'combo' || found.section.id !== 'window') return null
      const parts = found.item.parts
      if (!parts || parts.length !== 5) return null
      let frame = null
      parts.forEach((p) => {
        const vol = (p.size[0] || 0) * (p.size[1] || 0) * (p.size[2] || 0)
        if (!frame || vol > frame.vol) frame = { p, vol }
      })
      if (!frame) return null
      const s = frame.p.size
      return Math.abs(s[0]) >= Math.abs(s[2]) ? 'x' : 'z'
    }

    /** 构建某窗的滑动组：外框固定；两个窗扇（框+玻璃）分别挂到 g1（低端=左）/g2（高端=右） */
    function buildWindowSlide(key) {
      if (windowSlides[key]) return windowSlides[key]
      if (!root) return null
      const found = findItem(key, catalog)
      if (!found || found.kind !== 'combo' || found.section.id !== 'window') return null
      const axis = windowSlideAxis(key)
      if (!axis) return null
      const parts = found.item.parts
      if (!parts || parts.length !== 5) return null
      // 先按体积找出外框（固定件），排除后剩下 4 个窗扇（2 框 + 2 玻璃）
      let frame = null
      parts.forEach((p) => {
        const vol = (p.size[0] || 0) * (p.size[1] || 0) * (p.size[2] || 0)
        if (!frame || vol > frame.vol) frame = { p, vol }
      })
      const leaves = parts.filter((p) => p.mesh !== frame.p.mesh)
      if (leaves.length !== 4) return null
      // 窗扇按滑动轴坐标排序：低半组 = 左扇（g1）/ 高半组 = 右扇（g2）
      const sorted = [...leaves].sort((a, b) => {
        const ia = axis === 'x' ? 0 : 2
        return (a.center[ia] || 0) - (b.center[ia] || 0)
      })
      const lowParts = sorted.slice(0, 2)
      const highParts = sorted.slice(2, 4)
      // 滑动距离：catalog 的 size 已是米；g.position 是 root 局部坐标（原始单位），
      // 局部移动量 = 窗扇沿轴最大宽度（米）÷ root.scale，保证两扇框完全重合
      const ia = axis === 'x' ? 0 : 2
      const sashWM = Math.max(lowParts[0].size[ia] || 0, lowParts[1].size[ia] || 0, 0.09)
      const dist = Math.max(sashWM / (root.scale.x || 0.03), 0.02)

      const getMeshes = (list) => list.map((p) => meshes.find((m) => m.userData.partName === p.mesh)).filter(Boolean)

      // 两个滑动组：初始位置在各自窗扇包围盒中心（保持世界变换）；origPos 记录原始位置供关闭复位
      const mk = (leaf) => {
        const g = new THREE.Group()
        const b = new THREE.Box3()
        leaf.forEach((m) => b.expandByObject(m))
        g.position.copy(root.worldToLocal(b.getCenter(new THREE.Vector3())))
        g.userData.origPos = g.position.clone()
        root.add(g)
        const saved = leaf.map((m) => ({ m, parent: m.parent }))
        leaf.forEach((m) => g.attach(m))
        return { g, saved, axis }
      }
      windowSlides[key] = {
        g1: mk(getMeshes(lowParts)),
        g2: mk(getMeshes(highParts)),
        axis, dist, dir: ''
      }
      return windowSlides[key]
    }

    /** 窗滑动动画：按 dir 滑动到目标位置（'right' 左扇右移 / 'left' 右扇左移 / '' 回到原始位置） */
    function tweenWindow(key, dir, done) {
      const ws = buildWindowSlide(key)
      if (!ws) { if (done) done(); return }
      cancelAnimationFrame(windowAnims[key])
      const t0 = performance.now()
      const dur = 650
      const ease = (k) => (k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2)
      const dist = ws.dist
      const o1 = ws.g1.g.userData.origPos
      const o2 = ws.g2.g.userData.origPos
      // 目标分量（沿滑动轴）：right → g1 正移 dist；left → g2 负移 dist；'' → 都回原位
      const axisIdx = ws.axis === 'x' ? 'x' : 'z'
      const o1v = o1[axisIdx], o2v = o2[axisIdx]
      const t1 = (dir === 'right' ? o1v + dist : o1v)
      const t2 = (dir === 'left' ? o2v - dist : o2v)
      const f1 = ws.g1.g.position[axisIdx]
      const f2 = ws.g2.g.position[axisIdx]
      const step = (t) => {
        const k = Math.min((t - t0) / dur, 1)
        const e = ease(k)
        ws.g1.g.position[axisIdx] = f1 + (t1 - f1) * e
        ws.g2.g.position[axisIdx] = f2 + (t2 - f2) * e
        if (k < 1) windowAnims[key] = requestAnimationFrame(step)
        else { ws.dir = dir; if (done) done() }
      }
      windowAnims[key] = requestAnimationFrame(step)
    }

    /** 关闭后：窗扇挂回原父级、移除滑动组 */
    function restoreWindowSlide(key) {
      const ws = windowSlides[key]
      if (!ws) return
      ;[ws.g1, ws.g2].forEach((s) => {
        s.saved.forEach(({ m, parent }) => { if (parent) parent.attach(m) })
        s.g.removeFromParent()
      })
      delete windowSlides[key]
    }

    /* ===== 原始窗「上悬外开」（顶部铰链 / top-hung，下缘外推），如模型 22 的 W7/W8 =====
     * W7/W8 在 z 正端墙：外框（固定）+ 可开扇（厚，size_z≈0.035m，含上铰链/把手）+ 薄扇（固定）。
     * 开启机构：可开扇上缘与窗框顶部铰接（旋转轴 = 沿窗宽轴 x 的水平线，位于扇上缘），
     * 扇体绕该顶部水平轴转动、下缘向外（±z，由扇相对外框的外凸方向判定）推出 ~45°；外框与薄扇固定不动。 */
    const nativeWinSwingPivots = {} // key → { g, dir, saved, open }（dir = 外开方向符号 ±1）
    const nativeWinSwingAnims = {}  // key → animId
    const NATIVE_HOPPER_RAD = THREE.MathUtils.degToRad(45) // 上悬外开角度：下缘与墙面呈 45°

    /** 判断某窗是否为「上悬外开窗」（顶部铰链 / top-hung，下缘外推 45°）。
     * 判据按模型显式白名单 meta.features.hopperTop（如 22 → ['W7','W8']）。
     * 注意：曾按部件厚度几何判型（size_z>0.5m 等），但 catalog 尺寸已统一为米，
     * 22 的 W7/W8 窗扇实测厚度仅 ~0.035m，几何判型永不命中 → 必须用特征白名单。 */
    function isSwingOutWindow(item) {
      const list = features && Array.isArray(features.hopperTop) ? features.hopperTop : []
      return !!item && list.includes(item.id)
    }

    /** 构造某上悬外开窗的 pivot：厚扇（及其玻璃）绕「上缘水平轴」下推外开；外框+薄扇固定。 */
    function buildNativeWindowSwing(key) {
      if (nativeWinSwingPivots[key]) return nativeWinSwingPivots[key]
      if (!root) return null
      const found = findItem(key, catalog)
      if (!found || found.kind !== 'combo' || found.section.id !== 'window') return null
      const parts = found.item.parts
      if (!parts || !isSwingOutWindow(found.item)) return null
      // 1) 外框 = 体积最大件；厚扇 = size_z 最大的非外框件
      let frame = null, frameVol = -1
      parts.forEach((p) => {
        const vol = (p.size[0] || 0) * (p.size[1] || 0) * (p.size[2] || 0)
        if (vol > frameVol) { frameVol = vol; frame = p }
      })
      let thick = null
      parts.forEach((p) => {
        if (p.mesh === frame.mesh) return
        if (!thick || (p.size[2] || 0) > (thick.size[2] || 0)) thick = p
      })
      if (!thick) return null
      // 可开扇组 = 厚扇框 + 与其面内中心几乎重合的同扇玻璃；外框（frame）与另一扇固定不动，绝不入组。
      // 22 的 W7/W8 实测：同扇玻璃与厚扇面内中心距 ≈0.003m、与相邻固定扇中心距 ≈0.1m → 用 0.05m 面内邻域可安全区分。
      const tc = thick.center
      const groupParts = parts.filter((p) => {
        if (p.mesh === frame.mesh) return false // 外框固定（不得旋转）
        if (p.mesh === thick.mesh) return true
        const dx = (p.center[0] || 0) - (tc[0] || 0)
        const dy = (p.center[1] || 0) - (tc[1] || 0)
        const dz = (p.center[2] || 0) - (tc[2] || 0)
        return Math.hypot(dx, dy) < 0.05 && Math.abs(dz) < 0.08 // 仅同扇玻璃（面内重合、贴在同一扇上）
      })
      const getMeshes = (list) => list.map((p) => meshes.find((m) => m.userData.partName === p.mesh)).filter(Boolean)
      const leafMeshes = getMeshes(groupParts)
      if (!leafMeshes.length) return null
      // 2) 铰链：可开扇世界包围盒的「上缘」——旋转轴沿 x（水平、窗宽向），位于扇顶 y=max。
      const b = new THREE.Box3()
      leafMeshes.forEach((m) => b.expandByObject(m))
      const bcx = (b.min.x + b.max.x) / 2          // 窗宽向中点
      const hingeY = b.max.y                        // 上缘（顶部铰接高度）
      const zMid = (b.min.z + b.max.z) / 2          // 扇厚度方向中心（铰链穿过扇上缘中心平面）
      const g = new THREE.Group()
      g.position.copy(root.worldToLocal(new THREE.Vector3(bcx, hingeY, zMid)))
      root.add(g)
      const saved = leafMeshes.map((m) => ({ m, parent: m.parent }))
      leafMeshes.forEach((m) => {
        if (m.scale.x !== 1 || m.scale.y !== 1 || m.scale.z !== 1) {
          const geo = m.geometry.clone(); geo.scale(m.scale.x, m.scale.y, m.scale.z); m.geometry = geo; m.scale.set(1, 1, 1)
        }
        g.attach(m)
      })
      // 3) 开向：扇相对外框的外凸方向（z）。扇中心 z > 外框中心 z → 朝 +z 外开。
      const outSign = ((tc[2] || 0) - (frame.center ? frame.center[2] : 0)) >= 0 ? 1 : -1
      // 扇体自顶部铰链向下（-y）延伸：绕 x 旋转 θ 时下缘 z 位移 = -dy·sinθ。
      // 要下缘朝 +z 外开 → θ<0（-outSign×45°）；朝 -z 外开 → θ>0。dir 存外开符号。
      nativeWinSwingPivots[key] = { g, dir: outSign, saved, open: false }
      return nativeWinSwingPivots[key]
    }

    /** 上悬外开窗开/关动画（绕顶部水平 x 轴，rotation.x：0 ↔ dirX×45°，dirX = -dir） */
    function tweenNativeWindowSwing(key, open, done) {
      const p = buildNativeWindowSwing(key)
      if (!p) { if (done) done(); return }
      cancelAnimationFrame(nativeWinSwingAnims[key])
      const t0 = performance.now()
      const dur = 850
      const ease = (k) => (k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2)
      const dirX = -p.dir // 顶部铰链 + 下缘外推：见 buildNativeWindowSwing 推导
      const from = p.g.rotation.x
      const target = dirX * NATIVE_HOPPER_RAD * (open ? 1 : 0)
      const step = () => {
        const k = Math.min(1, (performance.now() - t0) / dur)
        const e = ease(k)
        p.g.rotation.x = from + (target - from) * e
        if (k < 1) nativeWinSwingAnims[key] = requestAnimationFrame(step)
        else { p.open = open; if (done) done() }
      }
      nativeWinSwingAnims[key] = requestAnimationFrame(step)
    }

    /** 上悬外开窗关闭后复位 */
    function restoreNativeWindowSwing(key) {
      const p = nativeWinSwingPivots[key]
      if (!p) return
      cancelAnimationFrame(nativeWinSwingAnims[key])
      p.g.rotation.set(0, 0, 0)
      // 先 attach 回原父级（pivot 仍在树内矩阵有效），最后移除 pivot（防门/窗扇飞回 GLB 原始坐标）
      p.saved.forEach(({ m, parent }) => { if (parent) parent.attach(m) })
      p.g.removeFromParent()
      delete nativeWinSwingPivots[key]
    }

    /** 切换外开窗开/关（open 语义） */
    function toggleNativeWindowSwing(key, open) {
      if (!root || !meshes.length) return
      editorState.windowSlide.key = key
      editorState.windowSlide.dir = open ? 'open' : ''
      if (open) tweenNativeWindowSwing(key, true)
      else tweenNativeWindowSwing(key, false, () => restoreNativeWindowSwing(key))
    }

    /* ===== 门平开（朝里开；如模型 22 的 door1：左右双扇绕各自外侧竖铰链朝室内 +X 旋转） =====
     * door1 在 X 负端墙（最外侧，x≈-47），门面法向 ±X，门宽沿 z。
     * 左扇（z 小端）绕 z 最小端竖铰链朝 +X 打开；右扇（z 大端）绕 z 最大端竖铰链朝 +X 打开；
     * 两扇在门洞中间（z≈0）合拢。与 21 门/素材门的约定一致：「铰链在 z 小端 → dir=+1；z 大端 → dir=-1，均朝室内 +X 打开」。
     * 检测：item.parts 中找两个 size_y > 0.4、0.12<=size_z<=0.22、size_x > 0.001（厚板；玻璃平面 size_x=0 排除）的 leaf frame，米为单位（catalog 已 scale）。
     */
    const doorSlides = {}   // key → { left:{g,saved,dir}, right:{g,saved,dir}, open:boolean }
    const doorSlideAnims = {}// key → animId
    const DOOR_SWING_RAD = THREE.MathUtils.degToRad(85)

    /** 判断一个门 item 是否为「双扇平开门」（两扇大玻璃/板门）。仅匹配叶子 frame（米）：
     *  size_y > 0.4（≈ 40cm 高），0.12 ≤ size_z ≤ 0.22（≈ 半扇宽 12-22cm），size_x > 0.001（厚板；玻璃 plane 的 size_x=0 排除）。 */
    function isSlidingDoor(item) {
      if (!item || !item.parts || item.parts.length < 4) return false
      let leafCount = 0
      for (const p of item.parts) {
        if (!p.size) continue
        const [sx, sy, sz] = p.size
        if (sy > 0.4 && sz >= 0.12 && sz <= 0.22 && sx > 0.001) leafCount++
        if (leafCount >= 2) return true
      }
      return false
    }

    /** 构造某门的平开 pivot：识别两个 leaf frame，把每个 frame 邻近的小件（把手/滚轮/玻璃/竖料）一起归组。
     *  每个 pivot 位置 = 该扇沿门宽轴「外侧」竖边的中点（世界 → root 局部），绕 Y 轴旋转朝室内 +X 打开。
     *  若该门已替换成素材门（holders[key]）：转用 buildHolderDoorPivot(key) 的素材门扇分组
     *  （left/right leaf + handle 随扇转，frame 固定），避免操作被隐藏的原始门 mesh。 */
    function buildDoorSlide(key) {
      if (doorSlides[key]) return doorSlides[key]
      if (!root) return null
      const found = findItem(key, catalog)
      if (!found || found.kind !== 'combo' || found.section.id !== 'door') return null
      // 素材门：素材替换后原始门 mesh 被隐藏，直接按素材 holder 建 pivot（参数化 buildHolderDoorPivot）
      if (holders[key]) {
        const pivots = buildHolderDoorPivot(key)
        if (!pivots || !pivots.length) return null
        doorSlides[key] = { left: pivots[0] || null, right: pivots[1] || null, open: false }
        return doorSlides[key]
      }
      const parts = found.item.parts
      if (!parts || !isSlidingDoor(found.item)) return null
      // 1) 找出两个 leaf frame（米阈值，与 isSlidingDoor 一致）
      const leaves = parts.filter((p) => {
        if (!p.size) return false
        const [sx, sy, sz] = p.size
        return sy > 0.4 && sz >= 0.12 && sz <= 0.22 && sx > 0.001
      })
      if (leaves.length !== 2) return null
      // 2) 门宽轴 = 门的水平跨度轴。door1 在 X- 端墙，门宽沿 z → axis='z'
      //    （若将来某门在 Z 端墙且宽沿 x，扩展为按 frame 长轴自动判定：|size_x|>|size_z| → 'x'）
      const ax = leaves[0].size
      const axis = Math.abs(ax[0]) > Math.abs(ax[2]) ? 'x' : 'z'
      const ia = axis === 'x' ? 0 : 2
      // 3) 排序：低半组 = 左扇 / 高半组 = 右扇
      const sorted = [...leaves].sort((a, b) => (a.center[ia] || 0) - (b.center[ia] || 0))
      const leftLeaf = sorted[0], rightLeaf = sorted[1]
      // 4) 找该 leaf 范围 ±leaf_z/2 + 1cm 内的所有小件 → 同一扇的子组件随主体一起旋转
      //    固定件（Color_M07 框/轨 + Mesh231 通长玻璃）显式排除，不跟随扇旋转
      const halfW = Math.max((leftLeaf.size[ia] || 0.15) / 2, 0.06)
      const isFixed = (p) => p.material === 'Color_M07.001' || (p.mesh || p.name) === 'Mesh231'
      const leftParts = []
      const rightParts = []
      for (const p of parts) {
        if (isFixed(p)) continue // 固定框/玻璃通片留在原处
        const dL = Math.abs((p.center[ia] || 0) - leftLeaf.center[ia])
        const dR = Math.abs((p.center[ia] || 0) - rightLeaf.center[ia])
        if (dL <= halfW + 0.01 && dL <= dR) leftParts.push(p)
        else if (dR <= halfW + 0.01) rightParts.push(p)
      }
      if (leftParts.length < 2 || rightParts.length < 2) return null

      const getMeshes = (list) => list.map((p) => meshes.find((m) => m.userData.partName === p.mesh)).filter(Boolean)

      // 每个扇建 pivot：pivot.position = 该扇世界包围盒「沿宽轴外侧」竖边的中点；
      // dir 按「铰链在宽轴小端 → +1，大端 → -1」定旋转方向，保证朝室内 +X 打开。
      const mk = (leafMeshes, dir) => {
        if (!leafMeshes.length) return null
        const b = new THREE.Box3()
        leafMeshes.forEach((m) => b.expandByObject(m))
        const yMid = (b.min.y + b.max.y) / 2
        const xMid = (b.min.x + b.max.x) / 2
        const hingeZ = dir === -1 ? b.max.z : b.min.z
        const hinge = new THREE.Vector3(xMid, yMid, hingeZ)
        const g = new THREE.Group()
        g.position.copy(root.worldToLocal(hinge))
        root.add(g)
        const saved = leafMeshes.map((m) => ({ m, parent: m.parent }))
        leafMeshes.forEach((m) => g.attach(m))
        return { g, saved, dir }
      }
      doorSlides[key] = {
        left: mk(getMeshes(leftParts), +1),   // 左扇绕 z 小端铰链
        right: mk(getMeshes(rightParts), -1), // 右扇绕 z 大端铰链
        open: false
      }
      return doorSlides[key]
    }

    /** 门平开/关闭动画（缓动）：pivot.rotation.y 从 0 ↔ dir*DOOR_SWING_RAD */
    function tweenDoorSlide(key, open, done) {
      const ds = buildDoorSlide(key)
      if (!ds) { if (done) done(); return }
      cancelAnimationFrame(doorSlideAnims[key])
      const t0 = performance.now()
      const dur = 800
      const leftFrom = ds.left ? ds.left.g.rotation.y : 0
      const leftTarget = ds.left ? ds.left.dir * DOOR_SWING_RAD * (open ? 1 : 0) : 0
      const rightFrom = ds.right ? ds.right.g.rotation.y : 0
      const rightTarget = ds.right ? ds.right.dir * DOOR_SWING_RAD * (open ? 1 : 0) : 0
      const step = () => {
        const k = Math.min(1, (performance.now() - t0) / dur)
        const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2
        if (ds.left) ds.left.g.rotation.y = leftFrom + (leftTarget - leftFrom) * e
        if (ds.right) ds.right.g.rotation.y = rightFrom + (rightTarget - rightFrom) * e
        if (k < 1) doorSlideAnims[key] = requestAnimationFrame(step)
        else { ds.open = open; if (done) done() }
      }
      doorSlideAnims[key] = requestAnimationFrame(step)
    }

    /** 关闭后：门扇 mesh 挂回原父级、移除 pivot */
    function restoreDoorSlide(key) {
      const ds = doorSlides[key]
      if (!ds) return
      ;[ds.left, ds.right].forEach((s) => {
        if (!s) return
        s.g.rotation.set(0, 0, 0)
        // 关键：必须先 attach 回原父级（此时 pivot 仍在场景树内，matrixWorld 有效，
        // attach 能正确保持世界变换）；最后才移除 pivot。顺序反了 pivot 先脱离场景树
        // 会导致 matrixWorld 失效，门扇被 attach 回 GLB 原始坐标（无 scale/居中）→ 门飞走。
        s.saved.forEach(({ m, parent }) => { if (parent) parent.attach(m) })
        s.g.removeFromParent()
      })
      delete doorSlides[key]
    }

    /** 切换门平开：open 语义。open=true 打开，false 关闭复位。
     *  模型 22 的真门（door1，X- 端墙朝内平开）开启动画结束后进入室内第一人称（同 21）；关闭后退出。 */
    function toggleDoorSlide(key, open = true) {
      if (!root || !meshes.length) return
      const ds = buildDoorSlide(key)
      if (!ds) return
      editorState.doorSlide.key = key
      editorState.doorSlide.dir = open ? 'open' : ''
      if (open) {
        // 通过门进入室内：若此前处于屋顶俯视/其他室内模式则先退出让位
        roofOverlook = false
        roofLookCenter = null
        // 复用门第一人称室内相机（enforceIndoorCamera 以 doorOpenState 为门控）
        if (!doorOpenState) { doorOpenState = true; roomBox = computeRoomBox() }
        tweenDoorSlide(key, true, () => {
          if (doorSlides[key] && doorSlides[key].open) enterRoom(key)
        })
      } else {
        tweenDoorSlide(key, false, () => {
          restoreDoorSlide(key)
          exitIndoor()
        })
      }
    }

    /* ===== 法式门平开（模型 22 门1/2/3：左右扇绕竖铰链朝 +Z 外各旋转 ~90°） =====
     * 与 21 swing（合并单 key='door' + X- 端墙 + enterRoom）完全独立；
     * 22 法式门每个 combo（door1/2/3）独立 key，独立 pivot，演示级动画。 */
    const FRENCH_DOOR_RAD = Math.PI / 2  // ±90°
    const frenchDoorPivots = {}    // key → { left:{g,saved,dir}, right:{g,saved,dir}, open }
    const frenchDoorAnims = {}     // key → animId
    let frenchDoorBtnEl = null     // 当前法式门浮动按钮

    /** 判定一个门 item 是否为法式门（非推拉门 + 至少 1 个外框 + 双扇结构）。
     *  当前命中：模型 22 的 door1/2/3（5 件式，门框 + 左/右扇各 1~2 mesh）。 */
    function isFrenchDoor(item) {
      if (!item || !item.parts || item.parts.length < 3) return false
      if (isSlidingDoor(item)) return false
      // 必须有 size_z 接近 0.43 的"门框"特征部件（典型法式门框厚度），否则当作未知结构
      const hasFrame = item.parts.some((p) => p.size && Math.abs(p.size[2] - 0.43) < 0.1 && Math.abs(p.size[0]) > 1 && Math.abs(p.size[1]) > 1)
      return hasFrame
    }

    /** 构造某法式门的两扇左右 pivot：每扇绕其**外侧**竖边（x 偏门中心方向的对端）为铰链，绕 Y 轴各旋转 ±π/2 朝门外侧打开。
     *  - 左扇（中心 x < 门框中心）：铰链 = leaf bbox min.x，旋转 -π/2（法向 +Z → -X，面面外左手边）
     *  - 右扇（中心 x > 门框中心）：铰链 = leaf bbox max.x，旋转 +π/2（法向 +Z → +X，面面外右手边） */
    function buildFrenchDoorPivot(key) {
      if (frenchDoorPivots[key]) return frenchDoorPivots[key]
      if (!root) return null
      const found = findItem(key, catalog)
      if (!found || found.kind !== 'combo' || found.section.id !== 'door') return null
      if (!isFrenchDoor(found.item)) return null
      const parts = found.item.parts
      // 1) 拆"门框"与"扇组"：门框 = size_z 接近 0.43 且 x 居中
      const itemCx = parts.reduce((s, p) => s + (p.center ? p.center[0] : 0), 0) / parts.length
      const frame = parts.find((p) =>
        p.size && Math.abs(p.size[2] - 0.43) < 0.1 && Math.abs((p.center ? p.center[0] : 0) - itemCx) < 1
      )
      const leaves = frame ? parts.filter((p) => p.mesh !== frame.mesh) : parts
      if (leaves.length < 1) return null
      // 2) 按 x 中心分左右两扇（door3 两扇同 x 中位，取首/末中点分）
      const sorted = [...leaves].sort((a, b) => (a.center ? a.center[0] : 0) - (b.center ? b.center[0] : 0))
      const midX = (sorted[0].center[0] + sorted[sorted.length - 1].center[0]) / 2
      let leftParts = sorted.filter((p) => (p.center ? p.center[0] : 0) < midX)
      let rightParts = sorted.filter((p) => (p.center ? p.center[0] : 0) >= midX)
      if (!leftParts.length) leftParts = sorted.slice(0, Math.ceil(sorted.length / 2))
      if (!rightParts.length) rightParts = sorted.slice(Math.ceil(sorted.length / 2))
      const getMeshes = (list) => list.map((p) => meshes.find((m) => m.userData.partName === p.mesh)).filter(Boolean)

      // 3) 每扇 pivot：pivot.position = leaf bbox 外侧竖边的中点（世界 → root 局部）
      const mkGroup = (leafMeshes, dir) => {
        if (!leafMeshes.length) return null
        const b = new THREE.Box3()
        leafMeshes.forEach((m) => b.expandByObject(m))
        const xMin = b.min.x, xMax = b.max.x
        const yMid = (b.min.y + b.max.y) / 2
        const zMid = (b.min.z + b.max.z) / 2
        const hingeX = dir === -1 ? xMin : xMax
        const pivot = new THREE.Group()
        pivot.position.copy(root.worldToLocal(new THREE.Vector3(hingeX, yMid, zMid)))
        pivot.userData.origPos = pivot.position.clone()
        root.add(pivot)
        const saved = leafMeshes.map((m) => ({ m, parent: m.parent }))
        leafMeshes.forEach((m) => pivot.attach(m))
        return { g: pivot, saved, dir }
      }
      const leftG = mkGroup(getMeshes(leftParts), -1)   // 左扇绕 min.x 铰链
      const rightG = mkGroup(getMeshes(rightParts), +1) // 右扇绕 max.x 铰链
      frenchDoorPivots[key] = { left: leftG, right: rightG, open: false }
      return frenchDoorPivots[key]
    }

    /** 法式门平开/关闭动画（缓动）：pivot.rotation.y 从 0 动画到 ±π/2 或反之 */
    function tweenFrenchDoor(key, open, done) {
      const fd = buildFrenchDoorPivot(key)
      if (!fd) { if (done) done(); return }
      cancelAnimationFrame(frenchDoorAnims[key])
      const t0 = performance.now()
      const dur = 850
      const leftFrom = fd.left ? fd.left.g.rotation.y : 0
      const leftTarget = fd.left ? -FRENCH_DOOR_RAD * (open ? 1 : 0) : 0
      const rightFrom = fd.right ? fd.right.g.rotation.y : 0
      const rightTarget = fd.right ? FRENCH_DOOR_RAD * (open ? 1 : 0) : 0
      const step = () => {
        const k = Math.min(1, (performance.now() - t0) / dur)
        const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2 // easeInOutQuad
        if (fd.left) fd.left.g.rotation.y = leftFrom + (leftTarget - leftFrom) * e
        if (fd.right) fd.right.g.rotation.y = rightFrom + (rightTarget - rightFrom) * e
        if (k < 1) frenchDoorAnims[key] = requestAnimationFrame(step)
        else { fd.open = open; if (done) done() }
      }
      frenchDoorAnims[key] = requestAnimationFrame(step)
    }

    /** 关闭后：拆 pivot、门扇 mesh 挂回原父级 */
    function restoreFrenchDoor(key) {
      const fd = frenchDoorPivots[key]
      if (!fd) return
      cancelAnimationFrame(frenchDoorAnims[key])
      ;[fd.left, fd.right].forEach((s) => {
        if (!s) return
        s.g.rotation.set(0, 0, 0)
        // 先 attach 回原父级（pivot 仍在树内矩阵有效），最后移除 pivot
        s.saved.forEach(({ m, parent }) => { if (parent) parent.attach(m) })
        s.g.removeFromParent()
      })
      delete frenchDoorPivots[key]
    }

    /** 切换某法式门的开/关（点击浮动按钮或面板按钮时调用） */
    function toggleFrenchDoor(key) {
      if (!root) return
      const fd = frenchDoorPivots[key] || buildFrenchDoorPivot(key)
      if (!fd) return
      fd.open = !fd.open
      editorState.frenchDoor.key = key
      editorState.frenchDoor.open = fd.open
      tweenFrenchDoor(key, fd.open)
    }

    /* ===== 素材窗外向平开（窗素材 01：左右窗扇绕各自外侧竖铰链向外开） ===== */
    // 仅整窗被替换成素材且素材含 left/right 窗扇时启用；铰链端与开口法向均按世界坐标动态判定，
    // 不依赖素材是否被 buildAssetReplacement 翻转（center.x 正负 / nAxis 不同都会自动适配）。
    const WINDOW_OPEN_RAD = THREE.MathUtils.degToRad(85)
    let windowSwingKey = '' // 当前处于平开状态的窗 key（同一时刻仅一扇平开，与门全局态一致）
    let windowPivots = null // 平开 pivot：{ g, dir, saved }
    let windowSwingAnim = 0

    /** 素材窗中属于左右窗扇（sash-left / sash-right）的 mesh；无 = 该素材没有可平开的扇。
     *  基于 assetMeshes 扫描（平开状态下窗扇挂到 pivot，holder.group.traverse 会漏 → 按钮误判为非平开素材）。 */
    function windowAssetSashMeshes(key) {
      if (!holders[key]) return null
      const list = assetMeshesOf(key).filter((o) => {
        const pn = o.userData.partName || ''
        return pn === key + '|sash-left' || pn === key + '|sash-right'
      })
      return list.length ? list : null
    }

    function normAng2Pi(a) {
      while (a > Math.PI) a -= Math.PI * 2
      while (a <= -Math.PI) a += Math.PI * 2
      return a
    }

    /**
     * 构建平开 pivot：每扇一个绕竖直铰链旋转的组。
     *  铰链 = 窗扇沿"窗宽轴"的外侧竖边（远离另一扇的一侧，即窗框立柱侧）；
     *  开启方向 = 让扇的自由边（铰链对侧、朝窗中心）转到素材正面（+X 世界方向 = 室外法向）。
     */
    function buildWindowSwingPivots(key) {
      const sashList = windowAssetSashMeshes(key)
      if (!sashList) return []
      const groups = { left: [], right: [] }
      sashList.forEach((m) => {
        const pn = m.userData.partName || ''
        if (pn === key + '|sash-left') groups.left.push(m)
        else if (pn === key + '|sash-right') groups.right.push(m)
      })
      const sides = [groups.left, groups.right].filter((arr) => arr.length)
      if (!sides.length) return []
      root.updateMatrixWorld(true)
      const boxes = sides.map((arr) => {
        const b = new THREE.Box3()
        arr.forEach((m) => b.expandByObject(m))
        return b
      })
      const centers = boxes.map((b) => b.getCenter(new THREE.Vector3()))
      if (centers.length < 2) {
        // 仅一侧扇（异常素材/部件被隐藏时）：无法确定宽轴 → 不做平开，避免越界抛错后“点开窗无反应”
        console.warn('[Viewer3D] 素材窗左右扇不齐，跳过向外平开：', key)
        return []
      }
      // 窗宽轴 = 左右两扇中心连线的水平分量
      const wAxis = new THREE.Vector3().subVectors(centers[1], centers[0])
      wAxis.y = 0
      if (wAxis.lengthSq() < 1e-8) return []
      wAxis.normalize()
      const winCenter = new THREE.Vector3().addVectors(centers[0], centers[1]).multiplyScalar(0.5)
      // 素材正面 +X 的世界方向（= 开口向外法向，窗扇要朝这里打开）
      const q = new THREE.Quaternion()
      holders[key].group.getWorldQuaternion(q)
      const outDir = new THREE.Vector3(1, 0, 0).applyQuaternion(q)
      outDir.y = 0
      if (outDir.lengthSq() < 1e-8) return []
      outDir.normalize()
      const phiOut = Math.atan2(outDir.z, outDir.x)
      const phiOf = (v) => Math.atan2(v.z, v.x)
      const pivots = []
      boxes.forEach((b, i) => {
        const bc = centers[i]
        // 铰链在沿宽轴"远离窗中心"那一端的扇棱
        const toC = { x: bc.x - winCenter.x, z: bc.z - winCenter.z }
        const outerSign = (toC.x * wAxis.x + toC.z * wAxis.z) >= 0 ? 1 : -1
        const pts = [[b.min.x, b.min.z], [b.min.x, b.max.z], [b.max.x, b.min.z], [b.max.x, b.max.z]]
        let best = null
        let bestD = null
        pts.forEach(([x, z]) => {
          const d = x * wAxis.x + z * wAxis.z
          if (bestD === null || (outerSign > 0 ? d > bestD : d < bestD)) {
            bestD = d
            best = [x, z]
          }
        })
        const hinge = new THREE.Vector3(best[0], bc.y, best[1])
        // 自由边方向（铰链 → 扇中心，水平）
        const dv = new THREE.Vector3(bc.x - hinge.x, 0, bc.z - hinge.z)
        if (dv.lengthSq() < 1e-8) return
        dv.normalize()
        const theta = normAng2Pi(phiOf(dv) - phiOut)
        const g = new THREE.Group()
        g.position.copy(root.worldToLocal(hinge))
        root.add(g)
        const saved = sides[i].map((m) => ({ m, parent: m.parent }))
        sides[i].forEach((m) => {
          // 素材 mesh 带非均匀 scale（buildAssetReplacement 的 kx/ky/kz）时先 bake 进几何再 attach，
          // 避免 pivot 旋转与父级非均匀缩放叠加产生扭曲（与 buildHolderDoorPivot 一致）
          if (m.scale.x !== 1 || m.scale.y !== 1 || m.scale.z !== 1) {
            const geo = m.geometry.clone()
            geo.scale(m.scale.x, m.scale.y, m.scale.z)
            m.geometry = geo
            m.scale.set(1, 1, 1)
          }
          g.attach(m)
        })
        pivots.push({ g, dir: theta < 0 ? -1 : 1, saved })
      })
      return pivots
    }

    /** 平开动画：rotation.y 在 0 ↔ dir*WINDOW_OPEN_RAD 间缓动 */
    function tweenWindowSwing(open, done) {
      if (!windowPivots || !windowPivots.length) {
        if (done) done()
        return
      }
      cancelAnimationFrame(windowSwingAnim)
      const t0 = performance.now()
      const dur = 850
      const ease = (k) => (k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2)
      const step = (t) => {
        const k = Math.min((t - t0) / dur, 1)
        const e = ease(k)
        const ang = open ? WINDOW_OPEN_RAD * e : WINDOW_OPEN_RAD * (1 - e)
        windowPivots.forEach((p) => { p.g.rotation.y = p.dir * ang })
        if (k < 1) windowSwingAnim = requestAnimationFrame(step)
        else if (done) done()
      }
      windowSwingAnim = requestAnimationFrame(step)
    }

    /** 平开关闭后：窗扇 mesh 挂回原父级、移除 pivot */
    function restoreWindowSwing() {
      if (!windowPivots) return
      windowPivots.forEach((p) => {
        p.saved.forEach(({ m, parent }) => { if (parent) parent.attach(m) })
        p.g.removeFromParent()
      })
      windowPivots = null
    }

    /** 素材窗 开/关（向外平开）。open = true 开 / false 关；新开另一扇时先把当前扇瞬间复位 */
    function applyWindowOpen(key, open) {
      if (!root) return
      if (open) {
        if (windowSwingKey === key && windowPivots) {
          editorState.windowOpen.key = key
          editorState.windowOpen.open = true
          return
        }
        if (windowPivots) {
          cancelAnimationFrame(windowSwingAnim)
          windowPivots.forEach((p) => { p.g.rotation.y = 0 })
          restoreWindowSwing()
        }
        windowSwingKey = ''
        const pivots = buildWindowSwingPivots(key)
        if (!pivots.length) {
          editorState.windowOpen.key = ''
          editorState.windowOpen.open = false
          return
        }
        windowSwingKey = key
        windowPivots = pivots
        editorState.windowOpen.key = key
        editorState.windowOpen.open = true
        tweenWindowSwing(true)
      } else {
        if (windowSwingKey !== key || !windowPivots) {
          if (windowPivots) {
            cancelAnimationFrame(windowSwingAnim)
            windowPivots.forEach((p) => { p.g.rotation.y = 0 })
            restoreWindowSwing()
            windowSwingKey = ''
          }
          if (editorState.windowOpen.key === key) {
            editorState.windowOpen.key = ''
            editorState.windowOpen.open = false
          }
          return
        }
        cancelAnimationFrame(windowSwingAnim)
        tweenWindowSwing(false, () => {
          restoreWindowSwing()
          windowSwingKey = ''
          editorState.windowOpen.key = ''
          editorState.windowOpen.open = false
        })
      }
    }

    /** 换窗素材 / 恢复原始部件前：若该窗正平开则瞬间归位（防止旧 pivot 带走窗扇 mesh） */
    function closeWindowSwingForSwap(key) {
      if (windowSwingKey !== key || !windowPivots) return
      cancelAnimationFrame(windowSwingAnim)
      windowPivots.forEach((p) => { p.g.rotation.y = 0 })
      restoreWindowSwing()
      windowSwingKey = ''
      editorState.windowOpen.key = ''
      editorState.windowOpen.open = false
    }

    /** 换窗素材 / 恢复原始部件前统一归位：平开素材窗瞬间合扇；原始推拉窗滑回原位并拆滑组 */
    function closeWindowBeforeSwap(key) {
      closeWindowSwingForSwap(key)
      const ws = windowSlides[key]
      if (ws) {
        if (ws.dir) {
          cancelAnimationFrame(windowAnims[key])
          ws.g1.g.position.copy(ws.g1.g.userData.origPos)
          ws.g2.g.position.copy(ws.g2.g.userData.origPos)
          ws.dir = ''
        }
        restoreWindowSlide(key)
      }
      if (editorState.windowSlide.key === key) {
        editorState.windowSlide.key = ''
        editorState.windowSlide.dir = ''
      }
      if (editorState.windowOpen.key === key) {
        editorState.windowOpen.key = ''
        editorState.windowOpen.open = false
      }
    }

    /** 切换窗户滑动：dir = 'left' | 'right' | ''。
     * 两段式语义：当前已开 dir 再点同向按钮 → 关闭；已开另一方向时点新方向 → 先滑回原位再向新方向开；
     * ''（关闭/关窗按钮）→ 直接滑回原位。 */
    function toggleWindow(key, dir = '') {
      if (!root || !meshes.length) return
      const cur = windowSlides[key]
      if (cur && cur.dir) {
        // 已打开
        if (dir && dir !== cur.dir) {
          // 切到另一方向：先回原位（不拆组），再向 dir 滑开
          editorState.windowSlide.key = key
          editorState.windowSlide.dir = dir
          cur.dir = dir
          tweenWindow(key, '', () => {
            const ws = windowSlides[key]
            if (ws) tweenWindow(key, dir)
          })
          return
        }
        // 同向点按 / dir='' → 关闭复位
        editorState.windowSlide.key = key
        editorState.windowSlide.dir = ''
        cur.dir = ''
        tweenWindow(key, '', () => restoreWindowSlide(key))
        return
      }
      // 未打开：dir 为空默认 'right'（左扇向右滑）
      const d = dir || 'right'
      editorState.windowSlide.key = key
      editorState.windowSlide.dir = d
      tweenWindow(key, d)
    }

    /* ===== 视角 ===== */
    /** 由部件包围盒计算观察方向：薄板沿法向轴从外侧看；实体沿中心方向 */
    function viewDirFor(center, size) {
      const arr = [size.x, size.y, size.z]
      const minI = arr.indexOf(Math.min(...arr))
      if (arr[minI] < 0.06) {
        const v = new THREE.Vector3()
        v.setComponent(minI, center.getComponent(minI) >= 0 ? 1 : -1)
        return v
      }
      const v = center.clone()
      if (v.lengthSq() < 1e-8) v.set(0, 0, 1)
      else v.normalize()
      return v
    }

    function meshesOfKey(key) {
      return meshes.filter((m) => m.userData.key === key)
    }

    /** 相机飞到某个选中键的正视角（部件库点击）：
     *  纯视角切换 —— 按部件大小自然取景距离，不做模型缩放；
     *  移动端底部抽屉开着时，仅把取景整体上移避开面板（只平移不改距离）。 */
    function flyToKey(key) {
      roofOverlook = false // 显式聚焦部件 → 退出屋顶俯视模式
      roofLookCenter = null
      const list = meshesOfKey(key)
      if (!list.length) return
      const box = new THREE.Box3()
      list.forEach((m) => box.expandByObject(m))
      const center = box.getCenter(new THREE.Vector3())
      const size = box.getSize(new THREE.Vector3())
      const dir = viewDirFor(center, size)
      const dist = Math.max(size.x, size.y, size.z) * 1.45 + 0.4 // 部件级取景距离：不缩放模型（比 1.7+0.55 更近）
      let pos = center.clone().addScaledVector(dir, dist)
      if (editorState.mobileSheetOpen) {
        // 旧平移基准作废 → 关闭抽屉时不会错误回跳；按“目标部件”重新只上移、不改变远近
        sheetPanOffset = null
        const off = computeSheetPan(box)
        if (off.lengthSq() > 1e-8) {
          sheetPanOffset = off
          pos.add(off)
        }
      }
      flyTo(sheetPanOffset ? center.clone().add(sheetPanOffset) : center, pos, 700)
    }

    /** 按当前模型包围盒动态计算常见视角（模型整体尺寸编辑后依然合理） */
    function presetView(name) {
      const preset = VIEW_PRESETS[name] || VIEW_PRESETS.front
      if (!root) return preset
      root.updateMatrixWorld(true)
      const box = getRootBox()
      const size = box.getSize(new THREE.Vector3())
      const center = box.getCenter(new THREE.Vector3())
      let d = Math.max(size.x, size.y, size.z) * 1.35 + 0.8
      // 窄屏（竖屏手机）：保证模型水平宽度完整入画，且四周留白更多（模型更小更远）
      if (camera && camera.aspect < 1) {
        const half = Math.max(size.x, size.z) / 2
        const fovRad = THREE.MathUtils.degToRad(camera.fov || 40)
        const hfov = 2 * Math.atan(Math.tan(fovRad / 2) * Math.max(camera.aspect, 0.1))
        const dW = (half * 1.35) / Math.tan(hfov / 2)
        if (dW > d) d = dW
      }
      const dir = new THREE.Vector3(...(VIEW_DIRS[name] || VIEW_DIRS.front)).normalize()
      return {
        pos: center.clone().addScaledVector(dir, d),
        target: center.clone()
      }
    }

    /** 平滑飞行（lerp 位置 + 目标点）。切换视角前若自动旋转开启，先暂停 */
    function flyTo(target, pos, dur = 650) {
      if (autoRotate.value) {
        autoRotate.value = false
        if (controls) controls.autoRotate = false
      }
      const fromPos = camera.position.clone()
      const fromTgt = controls.target.clone()
      cancelAnimationFrame(flyAnim)
      flyRunning = true // 飞行中不做室内钳制，避免与飞行动画互相干扰
      const t0 = performance.now()
      const ease = (k) => (k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2)
      const step = (t) => {
        const k = Math.min((t - t0) / dur, 1)
        const e = ease(k)
        camera.position.lerpVectors(fromPos, pos, e)
        controls.target.lerpVectors(fromTgt, target, e)
        controls.update()
        if (k < 1) {
          flyAnim = requestAnimationFrame(step)
        } else {
          flyRunning = false
        }
      }
      flyAnim = requestAnimationFrame(step)
    }

    function setView(name) {
      roofOverlook = false // 显式切换预设视角 → 退出屋顶俯视模式
      roofLookCenter = null
      const v = presetView(name)
      flyTo(v.target, v.pos)
    }

    /* ===== 移动端：底部抽屉开合 → 模型视角自动上移/复位（防面板遮挡模型） ===== */
    let sheetPanOffset = null // 当前生效的视角平移（世界米）；非空表示处于“为抽屉让位”的平移态

    /** 底部抽屉高度占比（与 RightPanel.vue CSS 响应式规则保持一致：58/74/70vh 且不超过视口-64px） */
    function mobileSheetFrac() {
      if (typeof window === 'undefined') return 0.58
      const h = window.innerHeight
      const maxFrac = Math.max(0, (h - 64) / Math.max(h, 1))
      if (h <= 480) return Math.min(0.74, maxFrac)
      if (window.innerWidth > h) return Math.min(0.7, maxFrac) // 横屏
      return Math.min(0.58, maxFrac)
    }

    /**
     * 计算让“模型中心”避开底部抽屉所需的世界平移量。
     * 原理：把相机与观察目标一起向下平移 d（世界 -Y），模型在屏幕上相对上移，
     * 且镜头朝向不变 —— 平滑自然、面板关闭后可原路还原。
     */
    function computeSheetPan(boxArg) {
      if (!root || !camera || !controls) return new THREE.Vector3()
      const b = boxArg || getRootBox()
      if (!b || b.isEmpty()) return new THREE.Vector3()
      const p = b.getCenter(new THREE.Vector3())
      const frac = mobileSheetFrac()
      const targetNdcY = sheetCenterNdcY(frac)
      const vN = p.clone().project(camera)
      if (vN.z > 1) return new THREE.Vector3() // 模型在视野后方：不调整
      const ndc0 = vN.y
      const p2 = p.clone().add(new THREE.Vector3(0, 0.1, 0)).project(camera)
      const slope = (p2.y - ndc0) / 0.1 // NDC y / 每米（世界 -Y 平移使模型上移 → 用此换算距离）
      let d = slope > 1e-4 ? (targetNdcY - ndc0) / slope : 0.38
      if (!isFinite(d)) d = 0.38
      d = Math.min(1.7, Math.max(0, d))
      return new THREE.Vector3(0, -d, 0)
    }

    /** 模型中心目标 NDC y（抽屉顶边明显上方；随抽屉高度自适应） */
    function sheetCenterNdcY(frac) {
      return Math.min(0.62, Math.max(0.16, 1 - frac + 0.1))
    }

    /**
     * 计算让模型在“抽屉上方可视区”内完整显示的取景放大系数：
     * 投影模型包围盒 8 角 → 需要模型 NDC 半高 ≤ 可用半高、半宽 ≤ 0.92，
     * 返回沿视线方向需要的距离放大倍率（>=1，必要时再缩小一点）。
     */
    function sheetFitFactor() {
      if (!camera) return 1
      const b = getRootBox()
      if (!b || b.isEmpty()) return 1
      const frac = mobileSheetFrac()
      const yC = sheetCenterNdcY(frac)
      const ndcSheetTop = -1 + 2 * frac // 抽屉顶边 NDC y
      const allowV = Math.max(0.12, Math.min(yC - ndcSheetTop, 1 - yC) - 0.06)
      const mn = b.min
      const mx = b.max
      let xMin = 1, xMax = -1, yMin = 1, yMax = -1
      for (let i = 0; i < 8; i++) {
        const c = new THREE.Vector3(
          i & 1 ? mx.x : mn.x,
          i & 2 ? mx.y : mn.y,
          i & 4 ? mx.z : mn.z
        ).project(camera)
        if (c.z > 1) continue
        if (c.x < xMin) xMin = c.x
        if (c.x > xMax) xMax = c.x
        if (c.y < yMin) yMin = c.y
        if (c.y > yMax) yMax = c.y
      }
      if (xMin > xMax || yMin > yMax) return 1
      const hW = (xMax - xMin) / 2
      const hV = (yMax - yMin) / 2
      let f = 1
      if (hV > allowV) f = Math.max(f, hV / allowV) // 垂直方向：全部塞进抽屉上方可视区
      if (hW > 0.94) f = Math.max(f, hW / 0.94) // 窄屏宽度方向保证完整
      return Math.min(f, 2.2) // 限制过度缩小
    }

    /** 面板开合切换 → 平滑平移+取景（复用 flyTo 缓动）：打开时上移并略缩小模型使其完整显示；关闭时原路还原 */
    function shiftViewForSheet(openNow) {
      if (!camera || !controls) return
      if (openNow) {
        if (sheetPanOffset) return // 已处于平移态（多次打开不再叠加）
        const off = computeSheetPan()
        if (off.lengthSq() < 1e-6) return
        sheetPanOffset = off
        const T0 = controls.target.clone().add(off)
        const C0 = camera.position.clone().add(off)
        const dir = new THREE.Vector3().subVectors(C0, T0)
        const r0 = dir.length()
        if (r0 < 1e-4) { flyTo(T0, C0, 600); return }
        dir.divideScalar(r0)
        const factor = sheetFitFactor() // ≥1：必要时后退一点让模型整体入画
        const C1 = T0.clone().addScaledVector(dir, r0 * factor)
        flyTo(T0, C1, 600)
      } else if (sheetPanOffset) {
        const off = sheetPanOffset
        sheetPanOffset = null
        flyTo(controls.target.clone().sub(off), camera.position.clone().sub(off), 600)
      }
    }

    function toggleAutoRotate() {
      autoRotate.value = !autoRotate.value
      if (controls) {
        controls.autoRotate = autoRotate.value
        controls.autoRotateSpeed = 2.2
      }
    }

    /* ===== 尺寸编辑 ===== */
    const r3 = (v) => Math.round(v * 1000) / 1000

    /** 计算某个选中键全部 Mesh 的世界包围盒（含替换素材） */
    function boxOfKey(key) {
      const list = meshesOfKey(key)
      if (!list.length) return null
      const box = new THREE.Box3()
      list.forEach((m) => box.expandByObject(m))
      const h = holders[key]
      if (h) box.union(new THREE.Box3().setFromObject(h.group))
      return box
    }

    /** 模型加载后回填整体与各选中键实际尺寸（米）到 editorState.sizes */
    function backfillSizes() {
      const box = getRootBox()
      editorState.sizes.model = {
        x: r3(box.max.x - box.min.x),
        y: r3(box.max.y - box.min.y),
        z: r3(box.max.z - box.min.z)
      }
      const parts = {}
      catalog.sections.forEach((sec) => {
        if (sec.type === 'combo-list') {
          sec.items.forEach((it) => {
            const b = boxOfKey(it.id)
            if (b) parts[it.id] = { x: r3(b.max.x - b.min.x), y: r3(b.max.y - b.min.y), z: r3(b.max.z - b.min.z) }
          })
        } else {
          sec.groups.forEach((g) => {
            g.parts.forEach((p) => {
              const b = boxOfKey(p.id)
              if (b) parts[p.id] = { x: r3(b.max.x - b.min.x), y: r3(b.max.y - b.min.y), z: r3(b.max.z - b.min.z) }
            })
          })
        }
      })
      editorState.sizes.parts = parts
      backfillPositions()
    }

    /** 模型加载后回填各选中键的世界中心位置（米），供属性面板位置编辑回显 */
    function backfillPositions() {
      const positions = {}
      catalog.sections.forEach((sec) => {
        if (sec.type === 'combo-list') {
          sec.items.forEach((it) => {
            const b = boxOfKey(it.id)
            if (b) {
              const c = b.getCenter(new THREE.Vector3())
              positions[it.id] = { x: r3(c.x), y: r3(c.y), z: r3(c.z) }
            }
          })
        } else {
          sec.groups.forEach((g) => {
            g.parts.forEach((p) => {
              const b = boxOfKey(p.id)
              if (b) {
                const c = b.getCenter(new THREE.Vector3())
                positions[p.id] = { x: r3(c.x), y: r3(c.y), z: r3(c.z) }
              }
            })
          })
        }
      })
      editorState.positions = positions
    }

    /** 首次编辑某选中键时，把组内 Mesh 挂到专用 Group（保持世界变换），之后统一缩放 */
    function ensureSizeGroup(key) {
      if (sizeGroups[key]) return sizeGroups[key]
      const list = meshesOfKey(key)
      if (!list.length) return null
      const g = new THREE.Group()
      root.add(g)
      list.forEach((m) => g.attach(m))
      sizeGroups[key] = g
      return g
    }

    /** 应用选中键（组合体/单部件）的目标尺寸；底部中心为缩放锚点，薄板轴保护 */
    function applyKeySize(key, newSize) {
      const g = ensureSizeGroup(key)
      if (!g) return
      // 已替换的组合体：替换体也挂入缩放 Group，随组统一缩放
      const h = holders[key]
      if (h && h.group.parent !== g) g.attach(h.group)
      root.updateMatrixWorld(true)
      const box = boxOfKey(key)
      if (!box) return
      const oldSize = box.getSize(new THREE.Vector3())
      const center = box.getCenter(new THREE.Vector3())
      const pivot = new THREE.Vector3(center.x, box.min.y, center.z)
      const k = new THREE.Vector3(
        oldSize.x > 1e-4 ? Math.max(0.01, newSize.x) / oldSize.x : 1,
        oldSize.y > 1e-4 ? Math.max(0.01, newSize.y) / oldSize.y : 1,
        oldSize.z > 1e-4 ? Math.max(0.01, newSize.z) / oldSize.z : 1
      )
      g.scale.multiply(k)
      // 保持底部中心锚点不动：position = pivot + (position - pivot) * k（root 局部空间）
      const pLocal = root.worldToLocal(pivot.clone())
      g.position.set(
        pLocal.x + (g.position.x - pLocal.x) * k.x,
        pLocal.y + (g.position.y - pLocal.y) * k.y,
        pLocal.z + (g.position.z - pLocal.z) * k.z
      )
      g.updateMatrixWorld(true)
      // 回写实际尺寸
      const nb = boxOfKey(key)
      if (nb) {
        editorState.sizes.parts[key] = {
          x: r3(nb.max.x - nb.min.x),
          y: r3(nb.max.y - nb.min.y),
          z: r3(nb.max.z - nb.min.z)
        }
      }
    }

    /** 移动选中键到指定世界中心坐标（米）；与尺寸共用编辑 Group，替换体一起移动 */
    function applyPartPos(key, pos) {
      const g = ensureSizeGroup(key)
      if (!g) return
      const h = holders[key]
      if (h && h.group.parent !== g) g.attach(h.group)
      root.updateMatrixWorld(true)
      // 当前世界中心 → root 局部；目标世界中心 → root 局部；增量平移（mesh 在组内偏移不影响中心）
      const box = boxOfKey(key)
      if (!box) return
      const curLocal = root.worldToLocal(box.getCenter(new THREE.Vector3()))
      const targetLocal = root.worldToLocal(new THREE.Vector3(pos.x, pos.y, pos.z))
      g.position.add(targetLocal.sub(curLocal))
      editorState.positions[key] = { x: r3(pos.x), y: r3(pos.y), z: r3(pos.z) }
    }

    /** 应用整体模型目标尺寸（保持 x/z 居中、底部贴地） */
    function applyModelSize(newSize) {
      if (!root) return
      const sx = Math.max(0.01, newSize.x) / MODEL_ORIG.x
      const sy = Math.max(0.01, newSize.y) / MODEL_ORIG.y
      const sz = Math.max(0.01, newSize.z) / MODEL_ORIG.z
      root.scale.set(sx, sy, sz)
      root.position.x = -baseCenter.x * sx
      root.position.y = 0
      root.position.z = -baseCenter.z * sz
      root.updateMatrixWorld(true)
      const box = getRootBox()
      editorState.sizes.model = {
        x: r3(box.max.x - box.min.x),
        y: r3(box.max.y - box.min.y),
        z: r3(box.max.z - box.min.z)
      }
      // 整体尺寸变化 → 重建标注
      rebuildDims()
    }

    /* ===== 整体尺寸标注 ===== */
    /** 模型根包围盒：只统计网格几何（expandByObject 在 r160 会递归子树，必须手动只对 mesh 叶节点扩展，
     *  否则尺寸标注组 dimGroup 的线条会撑大 box，导致整体尺寸回填错误）。
     *  存在主体簇（refreshCluster）时只统计主体部件，离群件（模型 22 的游离大板等）不计入取景/标注。 */
    function getRootBox() {
      const box = new THREE.Box3()
      if (!root) return box
      root.updateMatrixWorld(true) // 确保 mesh.matrixWorld 最新
      if (clusterMeshSet) {
        clusterMeshSet.forEach((o) => box.expandByObject(o))
        return box
      }
      const walk = (o) => {
        if (o === dimGroup) return
        if (o.isMesh) box.expandByObject(o)
        o.children.forEach(walk)
      }
      walk(root)
      return box
    }

    function makeLabel(cls, text) {
      const el = document.createElement('div')
      el.className = 'v3d-dim ' + cls
      el.textContent = text
      rootRef.value.appendChild(el)
      return el
    }
    function removeLabel(d) {
      if (d.el && d.el.parentNode) d.el.parentNode.removeChild(d.el)
    }
    /** 把世界坐标投影到屏幕，更新标注标签位置 */
    function placeLabel(el, pos) {
      const v = pos.clone().project(camera)
      if (v.z > 1) { el.style.display = 'none'; return }
      const w = rootRef.value.clientWidth
      const h = rootRef.value.clientHeight
      el.style.display = 'block'
      el.style.left = ((v.x * 0.5 + 0.5) * w) + 'px'
      el.style.top = ((-v.y * 0.5 + 0.5) * h) + 'px'
    }
    function updateDimLabels() {
      if (!showDims.value) return
      dimLabels.forEach((d) => placeLabel(d.el, d.pos))
      partDimLabels.forEach((d) => placeLabel(d.el, d.pos))
    }

    /**
     * 为指定包围盒构建三方向尺寸线 + 标签（root 局部线 + 世界坐标标签）。
     * 尺寸线与标签按轴分色：长(蓝) / 宽(绿) / 高(橙)。
     * @param {THREE.Box3} box 世界包围盒
     * @param {THREE.Group} group 尺寸线组（挂 root 下）
     * @param {Array} labels 标签收集数组 [{ el, pos }]
     * @param {(cls:string)=>void} onLabelClick 标签点击回调（可选）
     * @param {object} opts { clsPrefix, off }
     */
    const DIM_AXIS_COLORS = { len: 0x2563eb, wid: 0x0e9f6e, hei: 0xd97706 }
    function buildDimsForBox(box, group, labels, onLabelClick, opts = {}) {
      const prefix = opts.clsPrefix || 'v3d-dim-' // 整体 'v3d-dim-'；部件 'v3d-dim-part-'
      const mode = opts.mode || 'part'
      // 先刷新 root 矩阵：worldToLocal/localToWorld 必须用最新 matrixWorld，
      // 否则模型加载回调里（root.position 刚居中、渲染未跑）会换算错位
      root.updateMatrixWorld(true)
      const s = box.getSize(new THREE.Vector3())
      // root 局部坐标系（尺寸线随模型缩放）
      const min = root.worldToLocal(box.min.clone())
      const max = root.worldToLocal(box.max.clone())
      const ls = max.clone().sub(min)
      const offXz = Math.max(ls.x, ls.z) * (opts.off || 0.07)
      // 尺寸线贴模型外沿：地面（y≈0）+ 左前角竖线（旧版风格）
      const yBase = min.y + 0.02
      // 整体标注：标签抬高到模型中部，避免与底部状态条/UI重叠
      // 部件标注：标签贴近对应尺寸线，避免长/宽/高三个标签堆到同一位置
      const labelY = min.y + ls.y * 0.5
      // 每个轴向独立收集点（分色画线）
      const segs = []

      function dim(a, b, tickDir, text, cls, axis) {
        const pts = []
        pts.push(a.x, a.y, a.z, b.x, b.y, b.z)
        const tick = 0.6 * offXz
        pts.push(a.x, a.y, a.z, a.x + tickDir.x * tick, a.y + tickDir.y * tick, a.z + tickDir.z * tick)
        pts.push(b.x, b.y, b.z, b.x + tickDir.x * tick, b.y + tickDir.y * tick, b.z + tickDir.z * tick)
        segs.push({ axis, pts })
        const el = makeLabel(cls, text)
        if (onLabelClick) el.addEventListener('click', () => onLabelClick(cls))
        const mid = new THREE.Vector3().copy(a).add(b).multiplyScalar(0.5)
        const wp = new THREE.Vector3().copy(mid)
        if (mode === 'overall') {
          // 整体：长/宽/高标签
          const labelOff = Math.max(offXz * 0.8, 0.02)
          if (axis === 'len') {
            // 长度标签跟随地面 Z 向尺寸线（用户需求：显示在下方红框位置）
            wp.y = yBase + labelOff
            wp.x -= offXz * 0.25
          } else {
            // 宽/高保持中部高度，轻微外推避免重叠
            wp.y = labelY
            if (axis === 'wid') wp.z += offXz * 0.25
            else if (axis === 'hei') { wp.x -= offXz * 0.35; wp.z += offXz * 0.35 }
          }
        } else {
          // 部件：标签锚在对应尺寸线上，不同轴向天然错开
          const labelOff = Math.max(offXz * 0.8, 0.02)
          if (axis === 'len') {
            // 长度线沿 Z，标签在其上方
            wp.y = yBase + labelOff
            wp.x -= offXz * 0.25
          } else if (axis === 'wid') {
            // 宽度线沿 X，标签在其上方
            wp.y = yBase + labelOff
            wp.z += offXz * 0.25
          } else if (axis === 'hei') {
            // 高度线沿 Y，标签在其左前方
            wp.y = labelY
            wp.x -= labelOff
            wp.z += labelOff
          }
        }
        labels.push({ el, pos: root.localToWorld(wp) })
      }

      // 长度（Z 向）：模型左外侧地面；薄板轴（s.z≈0）跳过
      if (s.z > 0.001) {
        dim(
          new THREE.Vector3(min.x - offXz, yBase, min.z), new THREE.Vector3(min.x - offXz, yBase, max.z),
          new THREE.Vector3(0, 1, 0), `长 ${r3(s.z)} m`, `${prefix}len`, 'len'
        )
      }
      // 宽度（X 向）：模型前侧地面
      if (s.x > 0.001) {
        dim(
          new THREE.Vector3(min.x, yBase, max.z + offXz), new THREE.Vector3(max.x, yBase, max.z + offXz),
          new THREE.Vector3(0, 1, 0), `宽 ${r3(s.x)} m`, `${prefix}wid`, 'wid'
        )
      }
      // 高度（Y 向）：左前角竖线（旧版位置）
      if (s.y > 0.001) {
        dim(
          new THREE.Vector3(min.x - offXz, min.y, max.z + offXz), new THREE.Vector3(min.x - offXz, max.y, max.z + offXz),
          new THREE.Vector3(1, 0, 0), `高 ${r3(s.y)} m`, `${prefix}hei`, 'hei'
        )
      }

      // 每个轴向一条独立 LineSegments（按轴分色）
      segs.forEach((seg) => {
        const geo = new THREE.BufferGeometry()
        geo.setAttribute('position', new THREE.Float32BufferAttribute(seg.pts, 3))
        group.add(new THREE.LineSegments(geo, new THREE.LineBasicMaterial({ color: DIM_AXIS_COLORS[seg.axis] || 0x3a4856 })))
      })
    }

    /** 重建整体尺寸标注：长(Z) / 宽(X) / 高(Y) 尺寸线 + 可点击标签 */
    function rebuildDims() {
      if (!dimGroup) return
      dimGroup.clear()
      dimLabels.forEach(removeLabel)
      dimLabels.length = 0
      const box = getRootBox()
      if (box.isEmpty()) return
      buildDimsForBox(box, dimGroup, dimLabels, (cls) => {
        // 点击标签 → 切到整体设置并聚焦对应尺寸字段
        const field = { len: 'length', wid: 'width', hei: 'height' }[cls.replace('v3d-dim-', '').slice(0, 3)] || 'length'
        editorState.tab = 'overall'
        editorState.focusField = field
      }, { mode: 'overall' })
      dimGroup.visible = showDims.value
    }

    /** 清空选中部件标注 */
    function clearPartDims() {
      if (partDimGroup) partDimGroup.clear()
      partDimLabels.forEach(removeLabel)
      partDimLabels.length = 0
    }

    /** 重建当前选中部件的尺寸标注（含替换素材 holder）；对齐旧版：名称标签在顶部上方 + 三向尺寸标签 */
    function rebuildPartDims() {
      clearPartDims()
      if (!showDims.value || !root) return
      const sel = editorState.selected
      if (!sel) return
      const key = sel.kind === 'combo' ? sel.item.id : sel.part.id
      const box = boxOfKey(key)
      if (!box) return
      const h = holders[key]
      if (h) box.union(new THREE.Box3().setFromObject(h.group))
      // 部件名称标签：顶部上方（旧版 tag-label）
      const s = box.getSize(new THREE.Vector3())
      const c = box.getCenter(new THREE.Vector3())
      const nameEl = makeLabel('v3d-dim-part-name', sel.kind === 'combo' ? sel.item.name : sel.part.name)
      partDimLabels.push({
        el: nameEl,
        pos: new THREE.Vector3(c.x, box.max.y + Math.max(s.x, s.y, s.z) * 0.1 + 0.05, c.z)
      })
      buildDimsForBox(box, partDimGroup, partDimLabels, null, {
        color: 0x8a97a8, clsPrefix: 'v3d-dim-part-', off: 0.05
      })
      partDimGroup.visible = true
    }

    /** 切换尺寸标注显示（整体 + 选中部件） */
    function toggleDims() {
      showDims.value = !showDims.value
      editorState.showDims = showDims.value
      if (dimGroup) dimGroup.visible = showDims.value
      dimLabels.forEach((d) => { d.el.style.display = showDims.value ? 'block' : 'none' })
      if (showDims.value) {
        rebuildPartDims()
      } else {
        clearPartDims()
      }
    }

    /* ===== 全局显示 ===== */
    function applyGroupVisibility() {
      const vis = editorState.display.groups
      const pv = editorState.partVisible
      const kv = editorState.keyVisible
      meshes.forEach((m) => {
        // 分组显隐 + 替换隐藏 + 子部件单独显隐 + 当前选中项显隐（key / partName 双匹配）
        m.visible = vis[m.userData.groupId] !== false && !m.userData.replaced &&
          pv[m.userData.partName] !== false &&
          kv[m.userData.key] !== false && kv[m.userData.partName] !== false
      })
      Object.entries(holders).forEach(([key, h]) => {
        h.group.visible = vis[h.sectionId] !== false && kv[key] !== false
      })
      // 替换素材逐部件显隐：assetMeshes 持久记录每个素材 mesh（含开门时挂到 pivot 下的门扇），
      // 依据其 partName token（如 'W1|glass'）匹配 partVisible；未替换/组不可见则整体隐藏
      assetMeshes.forEach((m) => {
        const key = m.userData && m.userData.key
        const h = holders[key]
        m.visible = !!(h && vis[h.sectionId] !== false && kv[key] !== false && pv[m.userData.partName] !== false)
      })
    }

    /* ===== 尺寸 / 动画 ===== */
    function resize() {
      const w = rootRef.value.clientWidth
      const h = rootRef.value.clientHeight
      if (!w || !h) return
      camera.aspect = w / h
      camera.updateProjectionMatrix()
      renderer.setSize(w, h)
    }

    function animate() {
      if (disposed) return
      animId = requestAnimationFrame(animate)
      controls.update()
      // 门开着且相机处于内腔时，限制相机不穿出建筑边界（飞行动画期间让位）
      if (typeof enforceIndoorCamera === 'function') enforceIndoorCamera()
      renderer.render(scene, camera)
      updateDimLabels()
    }

    /* ===== 生命周期 ===== */
    onMounted(() => {
      initScene()
      loadModel()
      loadAssets() // 门窗素材库（sucai.glb）
    })

    onBeforeUnmount(() => {
      disposed = true
      cancelAnimationFrame(animId)
      cancelAnimationFrame(flyAnim)
      cancelAnimationFrame(doorAnim)
      hideDoorToggleBtn()
      hideDoorSlideToggleBtn()
      hideFrenchDoorToggleBtn()
      hideWinToggleBtn()
      hideRoofToggleBtn()
      Object.values(windowAnims).forEach((id) => cancelAnimationFrame(id))
      Object.values(doorSlideAnims).forEach((id) => cancelAnimationFrame(id))
      Object.values(frenchDoorAnims).forEach((id) => cancelAnimationFrame(id))
      // 关门复位：门扇挂回原父级
      if (doorPivots) restorePivots(doorPivots)
      // 关窗复位：素材平开 pivot 先归 0 再挂回原父级；滑动组直接拆
      cancelAnimationFrame(windowSwingAnim)
      if (windowPivots) {
        windowPivots.forEach((p) => { p.g.rotation.y = 0 })
        restoreWindowSwing()
      }
      Object.keys(windowSlides).forEach((k) => restoreWindowSlide(k))
      Object.keys(doorSlides).forEach((k) => restoreDoorSlide(k))
      Object.keys(frenchDoorPivots).forEach((k) => restoreFrenchDoor(k))
      Object.values(nativeWinSwingAnims).forEach((id) => cancelAnimationFrame(id))
      Object.keys(nativeWinSwingPivots).forEach((k) => restoreNativeWindowSwing(k))
      dimLabels.forEach(removeLabel)
      dimLabels.length = 0
      partDimLabels.forEach(removeLabel)
      partDimLabels.length = 0
      if (ro) ro.disconnect()
      if (renderer) {
        renderer.domElement.removeEventListener('pointerdown', onPointerDown)
        renderer.domElement.removeEventListener('pointerup', onPointerUp)
        renderer.domElement.removeEventListener('pointermove', onPointerMove)
        renderer.domElement.removeEventListener('pointercancel', onPointerCancel)
        controls.dispose()
        renderer.dispose()
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement)
      }
    })

    // 部件库选中 → 视口高亮联动
    watch(
      () => editorState.selected,
      (sel) => {
        syncHighlight(sel)
        // 选中变化 → 重建选中部件尺寸标注
        rebuildPartDims()
      }
    )

    // 部件库单击/双击 → 视角聚焦
    watch(
      () => editorState.focus.nonce,
      () => {
        if (editorState.focus.key) flyToKey(editorState.focus.key)
      }
    )

    // 分组显隐
    watch(
      () => ({ ...editorState.display.groups }),
      () => applyGroupVisibility(),
      { deep: true }
    )

    // 子部件显隐（partVisible 变化 → 重算所有 mesh 可见性）
    watch(
      () => ({ ...editorState.partVisible }),
      () => applyGroupVisibility(),
      { deep: true }
    )

    // 当前选中项显隐（keyVisible 变化 → 重算所有 mesh 可见性）
    watch(
      () => ({ ...editorState.keyVisible }),
      () => applyGroupVisibility(),
      { deep: true }
    )

    // 玻璃质感（透明度/磨砂/作用域变化 → 应用）
    watch(
      () => ({ ...editorState.glass }),
      () => applyGlassStyle(editorState.glass.scope || 'part'),
      { deep: true }
    )

    // 门窗玻璃独立设置（glassPerKey 增删改 → 应用；删除/回落 → 恢复全局默认）
    watch(
      () => editorState.glassPerKey,
      () => {
        Object.keys(editorState.glassPerKey).forEach((key) => {
          applyGlassPerKeyToKey(key, editorState.glassPerKey[key])
        })
        // 已回填但无 per-key 的组合体 → 回落全局默认（含刚被删除设置的 key）
        Object.keys(editorState.glassInfo).forEach((key) => {
          if (!(key in editorState.glassPerKey)) applyGlassPerKeyToKey(key, null)
        })
      },
      { deep: true }
    )

    // 网格地面开关
    watch(
      () => editorState.display.grid,
      (v) => {
        if (gridHelper) gridHelper.visible = v
      }
    )

    // 光照与背景控制
    watch(
      () => ({ ...editorState.lighting }),
      (l) => {
        if (hemiLight) hemiLight.intensity = l.hemi
        if (keyLight) {
          keyLight.intensity = l.key
          keyLight.position.set(l.dirX, l.dirY, l.dirZ)
        }
        if (fillLight) fillLight.intensity = l.fill
        if (scene && l.background) scene.background = new THREE.Color(l.background)
      },
      { deep: true }
    )

    // 尺寸编辑请求（key='model' 整体；否则选中键）
    watch(
      () => editorState.sizeEdit.nonce,
      () => {
        const req = editorState.sizeEdit
        if (!req.key || !req.size) return
        if (req.key === 'model') applyModelSize(req.size)
        else {
          applyKeySize(req.key, req.size)
          rebuildPartDims() // 部件尺寸变化 → 重建部件标注
        }
      }
    )

    // 素材替换 / 恢复请求（key = 窗/门组合体 id）
    watch(
      () => editorState.assetEdit.nonce,
      () => {
        const req = editorState.assetEdit
        if (!req.key) return
        if (req.restore) restoreAsset(req.key)
        else if (req.assetId) replaceWithAsset(req.key, req.assetId)
      }
    )

    // 门开合请求（属性面板按钮 → 开门/关门）
    watch(
      () => editorState.door.nonce,
      () => toggleDoor()
    )
    // 法式门平开（来自属性面板）：仅同步当前 combo 的状态到 pivot，并按 open 方向播放动画
    watch(
      () => editorState.frenchDoor.nonce,
      () => {
        const req = editorState.frenchDoor
        if (!req.key) return
        const fd = frenchDoorPivots[req.key] || buildFrenchDoorPivot(req.key)
        if (!fd) return
        if (fd.open !== req.open) {
          fd.open = req.open
          tweenFrenchDoor(req.key, req.open)
        }
      }
    )

    // 窗开合请求（属性面板按钮 → 外开窗平开 / 推拉窗向左滑·向右滑 / 关闭）
    watch(
      () => editorState.windowSlide.nonce,
      () => {
        const req = editorState.windowSlide
        if (!req.key) return
        const found = findItem(req.key, catalog)
        if (found && found.kind === 'combo' && isSwingOutWindow(found.item)) {
          toggleNativeWindowSwing(req.key, req.dir === 'open')
          return
        }
        toggleWindow(req.key, req.dir || '')
      }
    )

    // 门平开请求（属性面板按钮 → 开门 / 关门；仅双扇平开门生效）
    watch(
      () => editorState.doorSlide.nonce,
      () => {
        const req = editorState.doorSlide
        if (!req.key) return
        const found = findItem(req.key, catalog)
        if (!found || !isSlidingDoor(found.item)) return
        toggleDoorSlide(req.key, req.dir === 'open')
      }
    )

    // 素材窗外向平开请求（窗素材替换后：左右窗扇向外开 / 关）
    watch(
      () => editorState.windowOpen.nonce,
      () => {
        const req = editorState.windowOpen
        if (!req.key) return
        applyWindowOpen(req.key, !!req.open)
      }
    )

    // 墙体贴图应用请求（all=true 全部墙体；否则单部件 key）
    watch(
      () => editorState.textureEdit.nonce,
      () => {
        const req = editorState.textureEdit
        if (!req.texId) return
        applyWallTexture(req.key, req.texId, req.density, req.all)
      }
    )

    // 位置编辑请求（世界坐标，米）
    watch(
      () => editorState.posEdit.nonce,
      () => {
        const req = editorState.posEdit
        if (!req.key || !req.pos) return
        applyPartPos(req.key, req.pos)
      }
    )

    // 移动端底部抽屉开合 → 自动上移/复位模型视角（面板不遮挡模型）
    watch(
      () => editorState.mobileSheetOpen,
      (v) => shiftViewForSheet(!!v)
    )

    // 纹理上传请求：创建 THREE.Texture → 加入已上传列表 → 自动应用到当前选中墙体
    watch(
      () => editorState.uploadTexture.nonce,
      async () => {
        const req = editorState.uploadTexture
        if (!req.dataURL) return
        try {
          const tex = await loadUploadedTexture(req.dataURL)
          const id = 'up-' + Date.now()
          uploadCache[id] = tex
          editorState.textures.uploaded.push({ id, name: req.name })
          const sel = editorState.selected
          if (sel && sel.kind === 'part' && sel.section && sel.section.id === 'wall') {
            applyWallTexture(sel.part.id, id, editorState.textures.cur.density || 3, false)
          }
        } catch (err) {
          console.warn('上传纹理加载失败', err)
        }
      }
    )

    return { rootRef, mountRef, state, selectedName, autoRotate, showDims, toggleAutoRotate, toggleDims, setView }
  }
}
</script>

